mkdir -p /workspace/src; cat > /workspace/src/sit.rs <<'EOF'
// Situations of the parser state machine.

pub type Color = u32;
pub const BOLD: u32 = 1 << 24;
pub const ITAL: u32 = 1 << 25;
pub const COLOR_NORMAL: Color = 0;
pub const COLOR_KWD: Color = BOLD;
pub const COLOR_CMD: Color = 0xc00080;
pub const COLOR_VAR: Color = 0x3f7fcf;
pub const COLOR_LVAR: Color = 0x007fff;
pub const COLOR_DQ: Color = 0xff0000;
pub const COLOR_SQ: Color = 0xffcc55;
pub const COLOR_SQESC: Color = 0xff8000;
pub const COLOR_ESC: Color = 0xff0080 | BOLD;
pub const COLOR_CMT: Color = 0x789060 | BOLD | ITAL;
pub const COLOR_HERE: Color = 0x802000;
pub const COLOR_MAGIC: Color = 0xc000c0;

#[derive(Debug)]
pub enum SynErr {
    Eof,
    Pitfall { pos: usize, len: usize },
}

pub type PResult = Result<WhatNow, SynErr>;

pub enum Tr {
    Flush,
    FlushPopOnEof,
    Replace(Sit),
    Push(Sit),
    Pop,
}

pub struct WhatNow {
    pub tr: Tr,
    pub pre: usize,
    pub len: usize,
    pub alt: Option<Vec<u8>>,
}

impl WhatNow {
    pub fn is_push(&self) -> bool {
        matches!(self.tr, Tr::Push(_))
    }
    fn shift(mut self, by: usize) -> WhatNow {
        self.pre += by;
        self
    }
}

fn a(s: &[u8]) -> Option<Vec<u8>> {
    Some(s.to_vec())
}

pub fn flush(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len: 0, alt: None }
}
pub fn flush_alt(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len, alt }
}
pub fn flush_or_pop(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::FlushPopOnEof, pre, len: 0, alt: None }
}
pub fn push(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Push(s), pre, len, alt }
}
pub fn replace(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Replace(s), pre, len, alt }
}
pub fn pop(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Pop, pre, len, alt }
}

// ---------------------------------------------------------------- predicates

pub fn is_ws(c: u8) -> bool {
    c <= b' '
}
pub fn is_identhead(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphabetic()
}
pub fn is_identtail(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphanumeric()
}
pub fn is_word(c: u8) -> bool {
    !(c <= b' ' || matches!(c, b';' | b'&' | b'|' | b'<' | b'>' | b'(' | b')' | b'`'))
}
pub fn is_phantomfood(c: u8) -> bool {
    c >= b'+' && !matches!(c, b';' | b'<' | b'>' | b'?' | b'\\' | b'`' | b'|')
}
pub fn predlen(f: fn(u8) -> bool, h: &[u8]) -> usize {
    h.iter().take_while(|&&c| f(c)).count()
}
fn identlen(h: &[u8]) -> usize {
    if h.is_empty() || !is_identhead(h[0]) {
        return 0;
    }
    predlen(is_identtail, h)
}
fn word_at(h: &[u8]) -> &[u8] {
    &h[..predlen(is_word, h)]
}

/// After position j, skip double quotes; are braces needed (identifier tail or end of input follows)?
fn braces_needed_after(inp: &[u8], mut j: usize) -> bool {
    while j < inp.len() && inp[j] == b'"' {
        j += 1;
    }
    j >= inp.len() || is_identtail(inp[j])
}

// ---------------------------------------------------------------- triggers & contexts

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Trig {
    None,
    Paren,
    Backtick,
    CaseItem,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ctx {
    /// Unquoted argument context: expansions need quotes.
    Arg,
    /// Inside a phantom (inserted) double-quoted string.
    Phantom,
    /// Inside a real double-quoted string. `fresh` = at the very start of it.
    Dq { fresh: bool },
    /// Quoting is not needed (assignment, [[ ]], case ...).
    NoQuote,
}

// ---------------------------------------------------------------- situations

#[derive(Clone, Debug)]
pub enum Sit {
    Normal { trig: Trig, end_alt: Option<Vec<u8>> },
    Cmd { trig: Trig },
    Arg { trig: Trig },
    Lvalue { trig: Trig, name_len: usize, op_len: usize },
    Rvalue { trig: Trig },
    Vec,
    Dq { fresh: bool },
    Phantom,
    Sq,
    SqEsc,
    Extent { rem: usize, color: Color, end_alt: Option<Vec<u8>> },
    VarIdent { end_alt: Option<Vec<u8>> },
    VarBrace { end_alt: Option<Vec<u8>>, depth: usize, star: Option<usize> },
    Magic { end: u8 },
    Comment,
    Heredoc { delim: Vec<u8> },
    Test { trig: Trig },
    TestN { trig: Trig, insert: &'static [u8], started: bool },
    TestX { trig: Trig, op_len: usize, started: bool },
    For { trig: Trig },
    ForArr { phase: u8, pre: usize },
    CaseSubj,
    CaseBody,
    CasePattern,
    Pitfall { pos: usize, len: usize },
}

impl Sit {
    pub fn color(&self) -> Color {
        match self {
            Sit::Normal { .. } => COLOR_NORMAL,
            Sit::Cmd { .. } => COLOR_CMD,
            Sit::Arg { .. } => COLOR_NORMAL,
            Sit::Lvalue { .. } => COLOR_LVAR,
            Sit::Rvalue { .. } => COLOR_NORMAL,
            Sit::Vec => COLOR_NORMAL,
            Sit::Dq { .. } => COLOR_DQ,
            Sit::Phantom => COLOR_DQ,
            Sit::Sq => COLOR_SQ,
            Sit::SqEsc => COLOR_SQESC,
            Sit::Extent { color, .. } => *color,
            Sit::VarIdent { .. } => COLOR_VAR,
            Sit::VarBrace { .. } => COLOR_VAR,
            Sit::Magic { .. } => COLOR_MAGIC,
            Sit::Comment => COLOR_CMT,
            Sit::Heredoc { .. } => COLOR_HERE,
            Sit::Test { .. } => COLOR_CMD,
            Sit::TestN { .. } => COLOR_NORMAL,
            Sit::TestX { .. } => COLOR_NORMAL,
            Sit::For { .. } => COLOR_KWD,
            Sit::ForArr { .. } => COLOR_NORMAL,
            Sit::CaseSubj => COLOR_KWD,
            Sit::CaseBody => COLOR_NORMAL,
            Sit::CasePattern => COLOR_NORMAL,
            Sit::Pitfall { .. } => COLOR_NORMAL,
        }
    }

    /// Whether this situation, at end of input, may be popped.
    pub fn whatnow(&mut self, inp: &[u8], pos: usize) -> PResult {
        let h = &inp[pos..];
        match self {
            Sit::Normal { trig, end_alt } => normal(*trig, end_alt, inp, pos),
            Sit::Cmd { trig } => cmd(*trig, inp, pos),
            Sit::Arg { trig } => arg(*trig, inp, pos),
            Sit::Lvalue { trig, name_len, op_len } => {
                Ok(replace(*name_len, *op_len, None, Sit::Rvalue { trig: *trig }))
            }
            Sit::Rvalue { trig } => rvalue(*trig, inp, pos),
            Sit::Vec => vec_(inp, pos),
            Sit::Dq { fresh } => {
                let f = *fresh;
                *fresh = false;
                dq(f, inp, pos)
            }
            Sit::Phantom => phantom(inp, pos),
            Sit::Sq => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::SqEsc => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                    if c == b'\\' {
                        return Ok(push(i, 0, None, esc_extent()));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Extent { rem, end_alt, .. } => {
                if h.len() >= *rem {
                    Ok(pop(*rem, 0, end_alt.take()))
                } else {
                    *rem -= h.len();
                    Ok(flush(h.len()))
                }
            }
            Sit::VarIdent { end_alt } => {
                let n = predlen(is_identtail, h);
                Ok(pop(n, 0, end_alt.take()))
            }
            Sit::VarBrace { end_alt, depth, star } => {
                let mut i = 0;
                while i < h.len() {
                    if *star == Some(pos + i) {
                        *star = None;
                        return Ok(flush_alt(i, 1, a(b"@")));
                    }
                    let c = h[i];
                    if c == b'\\' {
                        i += 2;
                        continue;
                    }
                    if c == b'$' && h.get(i + 1) == Some(&b'{') {
                        *depth += 1;
                        i += 2;
                        continue;
                    }
                    if c == b'}' {
                        if *depth == 0 {
                            return Ok(pop(i, 1, end_alt.take()));
                        }
                        *depth -= 1;
                    }
                    i += 1;
                }
                Ok(flush(h.len()))
            }
            Sit::Magic { end } => magic(*end, inp, pos),
            Sit::Comment => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\n' {
                        return Ok(pop(i, 0, None));
                    }
                }
                Ok(flush_or_pop(h.len()))
            }
            Sit::Heredoc { delim } => {
                if let Some(idx) = find(h, delim) {
                    return Ok(pop(idx, delim.len(), None));
                }
                Ok(flush(h.len()))
            }
            Sit::Test { trig } => test(*trig, inp, pos),
            Sit::TestN { trig, insert, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, inp, pos)? {
                        return Ok(wn);
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                Ok(replace(0, 0, a(insert), Sit::Arg { trig: *trig }))
            }
            Sit::TestX { trig, op_len, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, inp, pos)? {
                        return Ok(wn);
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                let n = 2 + *op_len;
                let after = pos + n + 1;
                let alt: &[u8] = if after >= inp.len() || !is_word(inp[after]) { b"\"\"" } else { b"" };
                Ok(replace(n, 1, a(alt), Sit::Arg { trig: *trig }))
            }
            Sit::For { trig } => for_(*trig, inp, pos),
            Sit::ForArr { phase, pre } => match *phase {
                0 => {
                    *phase = 1;
                    Ok(flush_alt(*pre, 0, a(b"\"")))
                }
                1 => {
                    *phase = 2;
                    Ok(push(0, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"[@]}") }))
                }
                _ => Ok(pop(0, 0, a(b"\""))),
            },
            Sit::CaseSubj => case_subj(inp, pos),
            Sit::CaseBody => case_body(inp, pos),
            Sit::CasePattern => {
                for i in 0..h.len() {
                    if h[i] == b')' {
                        return Ok(replace(i, 1, None, Sit::Normal { trig: Trig::CaseItem, end_alt: None }));
                    }
                    if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, inp, pos + i)? {
                        return Ok(wn.shift(i));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Pitfall { pos, len } => Err(SynErr::Pitfall { pos: *pos, len: *len }),
        }
    }
}

fn find(h: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || needle.len() > h.len() {
        return if needle.is_empty() { Some(0) } else { None };
    }
    (0..=h.len() - needle.len()).find(|&i| &h[i..i + needle.len()] == needle)
}

fn esc_extent() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_ESC, end_alt: None }
}

fn extent0(color: Color) -> Sit {
    Sit::Extent { rem: 0, color, end_alt: None }
}

pub fn root() -> Sit {
    Sit::Normal { trig: Trig::None, end_alt: None }
}

// ---------------------------------------------------------------- command start

fn normal(trig: Trig, end_alt: &mut Option<Vec<u8>>, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if trig == Trig::CaseItem && c == b';' && h.get(i + 1) == Some(&b';') {
            return Ok(pop(i, 2, None));
        }
        if is_ws(c) || matches!(c, b';' | b'|' | b'&' | b'<' | b'>') {
            continue;
        }
        if trig == Trig::Paren && c == b')' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if trig == Trig::Backtick && c == b'`' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if c == b'\\' {
            return Ok(push(i, 0, None, esc_extent()));
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        return Ok(keyword_or_command(trig, inp, pos + i)?.shift(i));
    }
    if trig == Trig::None {
        Ok(flush_or_pop(h.len()))
    } else {
        Ok(flush(h.len()))
    }
}

fn lvalue_len(h: &[u8]) -> Option<(usize, usize)> {
    let n = identlen(h);
    if n == 0 {
        return None;
    }
    let mut j = n;
    if h.get(j) == Some(&b'[') {
        let close = h[j..].iter().position(|&c| c == b']')?;
        j += close + 1;
    }
    match h.get(j) {
        Some(b'=') => Some((j, 1)),
        Some(b'+') if h.get(j + 1) == Some(&b'=') => Some((j, 2)),
        _ => None,
    }
}

pub fn keyword_or_command(trig: Trig, inp: &[u8], p: usize) -> PResult {
    let h = &inp[p..];
    let c = h[0];
    if c == b'(' {
        if h.get(1) == Some(&b'(') {
            return Ok(push(0, 1, None, Sit::Magic { end: b')' }));
        }
        return Ok(push(0, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None }));
    }
    if let Some((name_len, op_len)) = lvalue_len(h) {
        return Ok(push(0, 0, None, Sit::Lvalue { trig, name_len, op_len }));
    }
    let len = predlen(is_word, h);
    let word = &h[..len];
    if trig == Trig::CaseItem && word == b"esac" {
        return Ok(pop(0, 0, a(b";; ")));
    }
    match word {
        b"[[" => Ok(push(0, 1, None, Sit::Magic { end: b']' })),
        b"case" => Ok(push(0, len, None, Sit::CaseSubj)),
        b"for" | b"select" => Ok(push(0, len, None, Sit::For { trig })),
        b"!" | b"declare" | b"do" | b"done" | b"elif" | b"else" | b"export" | b"fi" | b"function" | b"if"
        | b"local" | b"readonly" | b"then" | b"until" | b"while" | b"{" | b"}" => {
            Ok(push(0, len, None, extent0(COLOR_KWD)))
        }
        b"[" | b"test" => {
            if h.get(len) == Some(&b' ') && h.get(len + 1) != Some(&b' ') {
                Ok(push(0, len + 1, None, Sit::Test { trig }))
            } else {
                Ok(push(0, 0, None, Sit::Cmd { trig }))
            }
        }
        _ => Ok(push(0, 0, None, Sit::Cmd { trig })),
    }
}

fn is_end_trig(trig: Trig, c: u8) -> bool {
    (trig == Trig::Paren && c == b')') || (trig == Trig::Backtick && c == b'`')
}

fn cmd(trig: Trig, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return Ok(pop(i, 0, None));
        }
        if is_ws(c) {
            return Ok(replace(i, 0, None, Sit::Arg { trig }));
        }
        if c == b'(' {
            return Ok(replace(i, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None }));
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush_or_pop(h.len()))
}

fn arg(trig: Trig, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return Ok(pop(i, 0, None));
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush_or_pop(h.len()))
}

fn rvalue(trig: Trig, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) || matches!(c, b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return Ok(pop(i, 0, None));
        }
        if c == b'(' {
            return Ok(push(i, 1, None, Sit::Vec));
        }
        if let Some(wn) = common_token(Ctx::NoQuote, trig, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush_or_pop(h.len()))
}

fn vec_(inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if c == b')' {
            return Ok(pop(i, 1, None));
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        if let Some(wn) = common_token(Ctx::Arg, Trig::None, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush(h.len()))
}

fn dq(fresh: bool, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if c == b'"' {
            return Ok(pop(i, 1, None));
        }
        if c == b'\\' {
            return Ok(push(i, 0, None, esc_extent()));
        }
        if c == b'$' || c == b'`' {
            if let Some(wn) = common_token(Ctx::Dq { fresh: fresh && i == 0 }, Trig::None, inp, pos + i)? {
                return Ok(wn.shift(i));
            }
        }
    }
    Ok(flush(h.len()))
}

fn phantom(inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    let m = predlen(is_phantomfood, h);
    if m == h.len() {
        return Ok(pop(0, 0, a(b"\"")));
    }
    if h[m] == b'"' {
        return Ok(replace(m, 1, a(b""), Sit::Dq { fresh: true }));
    }
    if let Some(wn) = common_token(Ctx::Phantom, Trig::None, inp, pos + m)? {
        return Ok(wn.shift(m));
    }
    Ok(pop(0, 0, a(b"\"")))
}

fn magic(end: u8, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if c == end {
            return Ok(pop(i, 1, None));
        }
        if c == b'(' {
            return Ok(push(i, 1, None, Sit::Magic { end: b')' }));
        }
        if c == b'[' {
            return Ok(push(i, 1, None, Sit::Magic { end: b']' }));
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush(h.len()))
}

// ---------------------------------------------------------------- tokens

/// Handles quotes, escapes, expansions and heredocs. Returned WhatNow is relative to p.
pub fn common_token(ctx: Ctx, trig: Trig, inp: &[u8], p: usize) -> Result<Option<WhatNow>, SynErr> {
    let c = inp[p];
    let full = matches!(ctx, Ctx::Arg | Ctx::NoQuote);
    match c {
        b'\'' if full => Ok(Some(push(0, 1, None, Sit::Sq))),
        b'"' if full => Ok(Some(push(0, 1, None, Sit::Dq { fresh: true }))),
        b'\\' if full => Ok(Some(push(0, 0, None, esc_extent()))),
        b'<' if full => Ok(heredoc(inp, p)),
        b'`' => Ok(backtick(ctx, inp, p)),
        b'$' => Ok(dollar(ctx, inp, p)),
        _ => {
            let _ = trig;
            Ok(None)
        }
    }
}

fn heredoc(inp: &[u8], p: usize) -> Option<WhatNow> {
    let h = &inp[p..];
    if h.starts_with(b"<<<") {
        return Some(flush(3));
    }
    if !h.starts_with(b"<<") {
        return None;
    }
    let fail = Some(flush(2));
    let mut j = 2;
    if h.get(j) == Some(&b'-') {
        j += 1;
    }
    while j < h.len() && is_ws(h[j]) {
        j += 1;
    }
    let mut delim: Vec<u8> = Vec::new();
    loop {
        if j >= h.len() {
            return fail;
        }
        let c = h[j];
        if is_ws(c) {
            break;
        }
        match c {
            b'\'' => {
                let close = h[j + 1..].iter().position(|&x| x == b'\'');
                match close {
                    None => return fail,
                    Some(k) => {
                        delim.extend_from_slice(&h[j + 1..j + 1 + k]);
                        j += k + 2;
                    }
                }
            }
            b'"' => {
                j += 1;
                loop {
                    if j >= h.len() {
                        return fail;
                    }
                    let d = h[j];
                    if d == b'"' {
                        j += 1;
                        break;
                    }
                    if d == b'\\' {
                        if j + 1 >= h.len() {
                            return fail;
                        }
                        let e = h[j + 1];
                        match e {
                            b'"' | b'\\' | b'$' | b'`' => delim.push(e),
                            b'\n' => {}
                            _ => {
                                delim.push(d);
                                delim.push(e);
                            }
                        }
                        j += 2;
                        continue;
                    }
                    delim.push(d);
                    j += 1;
                }
            }
            b'\\' => {
                if j + 1 >= h.len() {
                    return fail;
                }
                if h[j + 1] != b'\n' {
                    delim.push(h[j + 1]);
                }
                j += 2;
            }
            _ => {
                delim.push(c);
                j += 1;
            }
        }
    }
    if delim.is_empty() {
        return Some(flush(j));
    }
    Some(push(0, j, None, Sit::Heredoc { delim }))
}

fn pwd(ctx: Ctx, inp: &[u8], p: usize, n: usize, is_backtick: bool) -> Option<WhatNow> {
    let needs = braces_needed_after(inp, p + n);
    let alt: &[u8] = if needs {
        if is_backtick && ctx == Ctx::NoQuote {
            return None;
        }
        b"${PWD}"
    } else {
        b"$PWD"
    };
    Some(push(0, n, a(alt), extent0(COLOR_VAR)))
}

fn backtick(ctx: Ctx, inp: &[u8], p: usize) -> Option<WhatNow> {
    let h = &inp[p..];
    if ctx == Ctx::Arg {
        return Some(push(0, 0, a(b"\""), Sit::Phantom));
    }
    if h.starts_with(b"`pwd`") {
        if let Some(wn) = pwd(ctx, inp, p, 5, true) {
            return Some(wn);
        }
    }
    match ctx {
        Ctx::NoQuote => Some(push(0, 1, None, Sit::Normal { trig: Trig::Backtick, end_alt: None })),
        _ => Some(push(0, 1, a(b"$("), Sit::Normal { trig: Trig::Backtick, end_alt: a(b")") })),
    }
}

fn pitfall_len(h: &[u8]) -> usize {
    1 + predlen(|c| c.is_ascii_digit(), &h[1..])
}

fn dollar(ctx: Ctx, inp: &[u8], p: usize) -> Option<WhatNow> {
    let h = &inp[p..];
    let c = match h.get(1) {
        None => return None,
        Some(&c) => c,
    };
    if c.is_ascii_digit() && h.get(2).map_or(false, |d| d.is_ascii_digit()) {
        return Some(push(0, 0, None, Sit::Pitfall { pos: p, len: pitfall_len(h) }));
    }
    if ctx == Ctx::Arg {
        let phantom = Some(push(0, 0, a(b"\""), Sit::Phantom));
        return match c {
            b'(' => {
                if h.get(2) == Some(&b'(') {
                    Some(push(0, 2, None, Sit::Magic { end: b')' }))
                } else {
                    phantom
                }
            }
            b'{' => {
                if matches!(h.get(2), Some(b'#') | Some(b'!')) {
                    Some(push(0, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None }))
                } else {
                    phantom
                }
            }
            b'\'' => Some(push(0, 2, None, Sit::SqEsc)),
            b'@' | b'*' | b'-' => phantom,
            b'?' | b'$' | b'!' | b'#' => Some(push(0, 0, None, var_extent2())),
            _ if c.is_ascii_digit() || is_identhead(c) => phantom,
            _ => None,
        };
    }
    match c {
        b'(' => {
            if h.get(2) == Some(&b'(') {
                return Some(push(0, 2, None, Sit::Magic { end: b')' }));
            }
            if h.starts_with(b"$(pwd)") {
                if let Some(wn) = pwd(ctx, inp, p, 6, false) {
                    return Some(wn);
                }
            }
            Some(push(0, 2, None, Sit::Normal { trig: Trig::Paren, end_alt: None }))
        }
        b'{' => Some(varbrace(ctx, inp, p)),
        b'\'' => {
            if ctx == Ctx::NoQuote {
                Some(push(0, 2, None, Sit::SqEsc))
            } else {
                None
            }
        }
        b'*' => {
            if ctx == Ctx::Phantom {
                Some(push(0, 2, a(b"$@"), extent0(COLOR_VAR)))
            } else {
                Some(push(0, 0, None, var_extent2()))
            }
        }
        b'@' | b'-' | b'?' | b'$' | b'!' | b'#' => Some(push(0, 0, None, var_extent2())),
        _ if c.is_ascii_digit() => Some(push(0, 0, None, var_extent2())),
        _ if is_identhead(c) => {
            if ctx == Ctx::Phantom {
                let n = identlen(&h[1..]);
                if braces_needed_after(inp, p + 1 + n) {
                    return Some(push(0, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"}") }));
                }
            }
            Some(push(0, 1, None, Sit::VarIdent { end_alt: None }))
        }
        _ => None,
    }
}

fn var_extent2() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_VAR, end_alt: None }
}

fn varbrace(ctx: Ctx, inp: &[u8], p: usize) -> WhatNow {
    let h = &inp[p..];
    let n = identlen(&h[2..]);
    let keep = Some(push(0, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None }));
    let plain = n > 0 && h.get(2 + n) == Some(&b'}');
    let after = p + 2 + n + 1;
    match ctx {
        Ctx::Phantom => {
            if plain && !braces_needed_after(inp, after) {
                return push(0, 2, a(b"$"), Sit::VarBrace { end_alt: a(b""), depth: 0, star: None });
            }
            if n > 0 && h[2 + n..].starts_with(b"[*]") {
                return push(0, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: Some(p + 2 + n + 1) });
            }
        }
        Ctx::Dq { fresh: true } => {
            if plain && inp.get(after) == Some(&b'"') && !braces_needed_after(inp, after) {
                return push(0, 2, a(b"$"), Sit::VarBrace { end_alt: a(b""), depth: 0, star: None });
            }
        }
        _ => {}
    }
    keep.unwrap()
}

// ---------------------------------------------------------------- test

fn test(trig: Trig, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    if h.starts_with(b"-n ") || h.starts_with(b"-z ") {
        if pos + 3 < inp.len() {
            if let Some(wn) = common_token(Ctx::Arg, trig, inp, pos + 3)? {
                if wn.is_push() {
                    let insert: &'static [u8] = if h[1] == b'n' { b" != \"\"" } else { b" = \"\"" };
                    return Ok(replace(0, 3, a(b""), Sit::TestN { trig, insert, started: false }));
                }
            }
        }
    }
    if h.first() == Some(&b'x') && pos + 1 < inp.len() {
        if let Ok(Some(wn)) = common_token(Ctx::Arg, trig, inp, pos + 1) {
            if wn.is_push() {
                if let Some(end) = crate::machine::simulate_token(inp, pos + 1, wn, trig) {
                    let r = &inp[end..];
                    let op_len = if r.starts_with(b" = x") {
                        Some(1)
                    } else if r.starts_with(b" == x") || r.starts_with(b" != x") {
                        Some(2)
                    } else {
                        None
                    };
                    if let Some(op_len) = op_len {
                        return Ok(replace(0, 1, a(b""), Sit::TestX { trig, op_len, started: false }));
                    }
                }
            }
        }
    }
    Ok(replace(0, 0, None, Sit::Arg { trig }))
}

// ---------------------------------------------------------------- for

fn for_(trig: Trig, inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if c == b'\n' || c == b';' {
            return Ok(pop(i, 0, None));
        }
        if is_ws(c) {
            continue;
        }
        if is_identhead(c) {
            let n = identlen(&h[i..]);
            if &h[i..i + n] == b"in" {
                if let Some(pre) = for_special(&h[i..]) {
                    return Ok(push(i, 0, None, Sit::ForArr { phase: 0, pre }));
                }
                return Ok(push(i, 0, None, Sit::Arg { trig }));
            }
            return Ok(push(i, n, None, extent0(COLOR_LVAR)));
        }
        let wn = keyword_or_command(trig, inp, pos + i)?.shift(i);
        return Ok(match wn.tr {
            Tr::Push(s) => WhatNow { tr: Tr::Replace(s), pre: wn.pre, len: wn.len, alt: wn.alt },
            other => WhatNow { tr: other, pre: wn.pre, len: wn.len, alt: wn.alt },
        });
    }
    Ok(flush(h.len()))
}

/// `in` + whitespace + `$ident` + spaces + (`;` | newline). Returns length of `in` + whitespace.
fn for_special(h: &[u8]) -> Option<usize> {
    let mut j = 2;
    while j < h.len() && (h[j] == b' ' || h[j] == b'\t') {
        j += 1;
    }
    if j == 2 {
        return None;
    }
    let pre = j;
    if h.get(j) != Some(&b'$') {
        return None;
    }
    let n = identlen(&h[j + 1..]);
    if n == 0 {
        return None;
    }
    j += 1 + n;
    while j < h.len() && h[j] == b' ' {
        j += 1;
    }
    match h.get(j) {
        Some(b';') | Some(b'\n') => Some(pre),
        _ => None,
    }
}

// ---------------------------------------------------------------- case

fn case_subj(inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            let r = &h[i + 1..];
            if r.starts_with(b"in") && r.get(2).map_or(true, |&d| !is_word(d)) {
                return Ok(replace(i + 3, 0, None, Sit::CaseBody));
            }
            continue;
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, inp, pos + i)? {
            return Ok(wn.shift(i));
        }
    }
    Ok(flush(h.len()))
}

fn case_body(inp: &[u8], pos: usize) -> PResult {
    let h = &inp[pos..];
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            continue;
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        if word_at(&h[i..]) == b"esac" {
            return Ok(replace(i, 4, None, extent0(COLOR_KWD)));
        }
        return Ok(push(i, 0, None, Sit::CasePattern));
    }
    Ok(flush(h.len()))
}
