mod machine;
mod sit;

use machine::{Mode, Sink};
use sit::SynErr;
use std::io::{Read, Seek, SeekFrom, Write};

const HELP: &[u8] = include_bytes!("help.txt");
const PITFALL: &[u8] = include_bytes!("pitfall.txt");
const EOF_MSG: &[u8] = b"Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.\n";

struct Ctx {
    rc: i32,
}

fn stdout_write(bytes: &[u8]) {
    let out = std::io::stdout();
    let mut lock = out.lock();
    let _ = lock.write_all(bytes);
    let _ = lock.flush();
}

fn stderr_write(bytes: &[u8]) {
    let err = std::io::stderr();
    let mut lock = err.lock();
    let _ = lock.write_all(bytes);
    let _ = lock.flush();
}

fn display_path(path: &str) -> &str {
    path
}

fn io_err_msg(path: &str, e: &std::io::Error) -> Vec<u8> {
    format!("{}: {}\n", display_path(path), e).into_bytes()
}

fn syn_err_msg(path: &str, inp: &[u8], e: &SynErr) -> Vec<u8> {
    let mut m = Vec::new();
    m.extend_from_slice(display_path(path).as_bytes());
    m.extend_from_slice(b": ");
    match e {
        SynErr::Eof => m.extend_from_slice(EOF_MSG),
        SynErr::Pitfall { pos, len } => {
            m.extend_from_slice(b"Unsupported syntax: Syntactic pitfall\n");
            let start = inp[..*pos].iter().rposition(|&c| c == b'\n').map_or(0, |x| x + 1);
            let end = inp[*pos..].iter().position(|&c| c == b'\n').map_or(inp.len(), |x| x + pos);
            m.extend_from_slice(&inp[start..end]);
            m.push(b'\n');
            for _ in start..*pos {
                m.push(b' ');
            }
            for _ in 0..*len {
                m.push(b'^');
            }
            m.push(b'\n');
            m.extend_from_slice(PITFALL);
        }
    }
    m
}

fn read_all<R: Read>(r: &mut R) -> std::io::Result<Vec<u8>> {
    let mut v = Vec::new();
    r.read_to_end(&mut v)?;
    Ok(v)
}

fn treat(path: &str, mode: Mode, ctx: &mut Ctx) {
    let is_stdin = path.is_empty();
    let replace_file = mode == Mode::Replace && !is_stdin;
    let effective = if mode == Mode::Replace && is_stdin { Mode::Transform } else { mode };

    // Obtain input.
    let mut file = None;
    let input: std::io::Result<Vec<u8>> = if is_stdin {
        read_all(&mut std::io::stdin().lock())
    } else {
        match std::fs::File::open(path) {
            Err(e) => {
                stderr_write(&io_err_msg(path, &e));
                ctx.rc = 1;
                return;
            }
            Ok(mut f) => {
                let r = if replace_file {
                    f.seek(SeekFrom::End(0)).and_then(|_| f.seek(SeekFrom::Start(0))).and_then(|_| read_all(&mut f))
                } else {
                    read_all(&mut f)
                };
                file = Some(f);
                r
            }
        }
    };
    let _ = file;
    let input = match input {
        Ok(v) => v,
        Err(e) => {
            match effective {
                Mode::Replace | Mode::Check => {}
                _ => {
                    let mut s = Sink::new(effective);
                    s.finish();
                    s.buf.push(b'\n');
                    stdout_write(&s.buf);
                }
            }
            stderr_write(&io_err_msg(path, &e));
            ctx.rc = 1;
            return;
        }
    };

    let mut sink = Sink::new(effective);
    let res = machine::run(&input, &mut sink);
    match res {
        Err(e) => {
            if effective == Mode::Check {
                std::process::exit(2);
            }
            if effective != Mode::Replace {
                sink.finish();
                sink.buf.push(b'\n');
                stdout_write(&sink.buf);
            }
            stderr_write(&syn_err_msg(path, &input, &e));
            ctx.rc = 1;
        }
        Ok(()) => {
            sink.finish();
            match effective {
                Mode::Check => {
                    if sink.buf != input {
                        std::process::exit(2);
                    }
                }
                Mode::Replace => {
                    if sink.buf != input {
                        let w = std::fs::OpenOptions::new().write(true).truncate(true).open(path);
                        match w {
                            Err(e) => {
                                stderr_write(&io_err_msg(path, &e));
                                ctx.rc = 1;
                            }
                            Ok(mut f) => {
                                if let Err(e) = f.write_all(&sink.buf) {
                                    stderr_write(&io_err_msg(path, &e));
                                    ctx.rc = 1;
                                }
                            }
                        }
                    }
                }
                _ => stdout_write(&sink.buf),
            }
        }
    }
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(1).collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut opts = true;
    let mut ctx = Ctx { rc: 0 };
    for arg in args {
        let s = arg.to_string_lossy().into_owned();
        if opts && s.starts_with('-') {
            match s.as_str() {
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                "--" => opts = false,
                "-h" | "--help" => stdout_write(HELP),
                "--version" => stdout_write(b"4.3.1\n"),
                _ => {
                    stderr_write(format!("{}: No such option.\n", s).as_bytes());
                    std::process::exit(3);
                }
            }
            continue;
        }
        treat(&s, mode, &mut ctx);
    }
    std::process::exit(ctx.rc);
}
