// Situations of the parser state machine. Each situation looks at a horizon
// (a window of upcoming input) and decides what to do next.

pub type Color = u32;
pub const BOLD: u32 = 1 << 24;
pub const ITAL: u32 = 1 << 25;
pub const COLOR_NORMAL: Color = 0;
pub const COLOR_KWD: Color = BOLD;
pub const COLOR_CMD: Color = 0xc00080;
pub const COLOR_VAR: Color = 0x3f7fcf;
pub const COLOR_LVAR: Color = 0x007fff;
pub const COLOR_DQ: Color = 0xff0000;
pub const COLOR_SQ: Color = 0xffcc55;
pub const COLOR_SQESC: Color = 0xff8000;
pub const COLOR_ESC: Color = 0xff0080 | BOLD;
pub const COLOR_CMT: Color = 0x789060 | BOLD | ITAL;
pub const COLOR_HERE: Color = 0x802000;
pub const COLOR_MAGIC: Color = 0xc000c0;

#[derive(Debug)]
pub enum SynErr {
    Eof,
    /// Position relative to the start of the horizon given to whatnow, length.
    Pitfall { pos: usize, len: usize },
}

pub type PResult = Result<WhatNow, SynErr>;

pub enum Tr {
    Flush,
    FlushPopOnEof,
    Replace(Sit),
    Push(Sit),
    Pop,
}

pub struct WhatNow {
    pub tr: Tr,
    pub pre: usize,
    pub len: usize,
    pub alt: Option<Vec<u8>>,
}

impl WhatNow {
    pub fn is_push(&self) -> bool {
        matches!(self.tr, Tr::Push(_))
    }
    pub fn is_flush(&self) -> bool {
        matches!(self.tr, Tr::Flush | Tr::FlushPopOnEof)
    }
}

fn a(s: &[u8]) -> Option<Vec<u8>> {
    Some(s.to_vec())
}

pub fn flush(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len: 0, alt: None }
}
pub fn flush_alt(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len, alt }
}
pub fn flush_or_pop(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::FlushPopOnEof, pre, len: 0, alt: None }
}
pub fn push(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Push(s), pre, len, alt }
}
pub fn replace(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Replace(s), pre, len, alt }
}
pub fn pop(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Pop, pre, len, alt }
}

// ---------------------------------------------------------------- predicates

pub fn is_ws(c: u8) -> bool {
    c <= b' '
}
pub fn is_identhead(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphabetic()
}
pub fn is_identtail(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphanumeric()
}
pub fn is_word(c: u8) -> bool {
    !(c <= b' ' || matches!(c, b';' | b'&' | b'|' | b'<' | b'>' | b'(' | b')' | b'`'))
}
pub fn is_phantomfood(c: u8) -> bool {
    c >= b'+' && !matches!(c, b';' | b'<' | b'>' | b'?' | b'\\' | b'`' | b'|')
}
pub fn predlen(f: fn(u8) -> bool, h: &[u8]) -> usize {
    h.iter().take_while(|&&c| f(c)).count()
}
fn identlen(h: &[u8]) -> usize {
    if h.is_empty() || !is_identhead(h[0]) {
        return 0;
    }
    predlen(is_identtail, h)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Tri {
    No,
    Yes,
    Maybe,
}

/// After position j, skip double quotes; are braces needed (identifier tail follows)?
/// Maybe if the horizon ends.
fn braces_needed_after(h: &[u8], mut j: usize) -> Tri {
    while j < h.len() && h[j] == b'"' {
        j += 1;
    }
    if j >= h.len() {
        Tri::Maybe
    } else if is_identtail(h[j]) {
        Tri::Yes
    } else {
        Tri::No
    }
}

// ---------------------------------------------------------------- triggers & contexts

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Trig {
    None,
    Paren,
    Backtick,
    CaseItem,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ctx {
    /// Unquoted argument context: expansions need quotes.
    Arg,
    /// Inside a phantom (inserted) double-quoted string.
    Phantom,
    /// Inside a real double-quoted string. `fresh` = at the very start of it.
    Dq { fresh: bool },
    /// Quoting is not needed (assignment, [[ ]], case ...).
    NoQuote,
}

fn is_end_trig(trig: Trig, c: u8) -> bool {
    (trig == Trig::Paren && c == b')') || (trig == Trig::Backtick && c == b'`')
}

// ---------------------------------------------------------------- situations

#[derive(Clone, Debug)]
pub enum Sit {
    Normal { trig: Trig, end_alt: Option<Vec<u8>> },
    Cmd { trig: Trig },
    Arg { trig: Trig },
    Lvalue { trig: Trig, name_len: usize, op_len: usize },
    Rvalue { trig: Trig },
    Vec,
    Dq { fresh: bool },
    Phantom { trig: Trig },
    StarPhantom { phase: u8 },
    Sq,
    SqEsc,
    Extent { rem: usize, color: Color, end_alt: Option<Vec<u8>> },
    VarIdent { end_alt: Option<Vec<u8>> },
    VarBrace { end_alt: Option<Vec<u8>>, depth: usize, star: Option<usize> },
    Magic { end: u8 },
    Comment,
    Heredoc { delim: Vec<u8> },
    Test { trig: Trig },
    TestN { trig: Trig, insert: &'static [u8], started: bool },
    TestX { trig: Trig, op_len: usize, started: bool },
    For { trig: Trig },
    ForArr { phase: u8, pre: usize },
    CaseSubj,
    CaseBody,
    CasePattern,
    Pitfall { len: usize },
}

impl Sit {
    pub fn color(&self) -> Color {
        match self {
            Sit::Normal { .. } => COLOR_NORMAL,
            Sit::Cmd { .. } => COLOR_CMD,
            Sit::Arg { .. } => COLOR_NORMAL,
            Sit::Lvalue { .. } => COLOR_LVAR,
            Sit::Rvalue { .. } => COLOR_NORMAL,
            Sit::Vec => COLOR_NORMAL,
            Sit::Dq { .. } => COLOR_DQ,
            Sit::Phantom { .. } => COLOR_DQ,
            Sit::StarPhantom { .. } => COLOR_VAR,
            Sit::Sq => COLOR_SQ,
            Sit::SqEsc => COLOR_SQESC,
            Sit::Extent { color, .. } => *color,
            Sit::VarIdent { .. } => COLOR_VAR,
            Sit::VarBrace { .. } => COLOR_VAR,
            Sit::Magic { .. } => COLOR_MAGIC,
            Sit::Comment => COLOR_CMT,
            Sit::Heredoc { .. } => COLOR_HERE,
            Sit::Test { .. } => COLOR_CMD,
            Sit::TestN { .. } => COLOR_NORMAL,
            Sit::TestX { .. } => COLOR_NORMAL,
            Sit::For { .. } => COLOR_KWD,
            Sit::ForArr { .. } => COLOR_NORMAL,
            Sit::CaseSubj => COLOR_KWD,
            Sit::CaseBody => COLOR_NORMAL,
            Sit::CasePattern => COLOR_NORMAL,
            Sit::Pitfall { .. } => COLOR_NORMAL,
        }
    }

    pub fn whatnow(&mut self, h: &[u8], l: bool) -> PResult {
        match self {
            Sit::Normal { trig, end_alt } => normal(*trig, end_alt, h, l),
            Sit::Cmd { trig } => Ok(cmd(*trig, h, l)),
            Sit::Arg { trig } => Ok(arg(*trig, h, l)),
            Sit::Lvalue { trig, name_len, op_len } => {
                Ok(replace(*name_len, *op_len, None, Sit::Rvalue { trig: *trig }))
            }
            Sit::Rvalue { trig } => Ok(rvalue(*trig, h, l)),
            Sit::Vec => Ok(vec_(h, l)),
            Sit::Dq { fresh } => {
                let wn = dq(*fresh, h, l);
                if !(wn.is_flush() && wn.pre == 0 && wn.len == 0) {
                    *fresh = false;
                }
                Ok(wn)
            }
            Sit::Phantom { trig } => Ok(phantom(*trig, h, l)),
            Sit::StarPhantom { phase } => {
                if *phase == 0 {
                    *phase = 1;
                    Ok(flush_alt(0, 2, a(b"$@")))
                } else {
                    Ok(pop(0, 0, a(b"\"")))
                }
            }
            Sit::Sq => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::SqEsc => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                    if c == b'\\' {
                        return Ok(push(i, 0, None, esc_extent()));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Extent { rem, end_alt, .. } => {
                if h.len() >= *rem {
                    Ok(pop(*rem, 0, end_alt.take()))
                } else {
                    *rem -= h.len();
                    Ok(flush(h.len()))
                }
            }
            Sit::VarIdent { end_alt } => {
                let n = predlen(is_identtail, h);
                if n == h.len() && l {
                    return Ok(flush(n));
                }
                Ok(pop(n, 0, end_alt.take()))
            }
            Sit::VarBrace { end_alt, depth, star } => varbrace_sit(end_alt, depth, star, h, l),
            Sit::Magic { end } => Ok(magic(*end, h, l)),
            Sit::Comment => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\n' {
                        return Ok(pop(i, 0, None));
                    }
                }
                Ok(flush_or_pop(h.len()))
            }
            Sit::Heredoc { delim } => {
                let dl = delim.len();
                let mut i = 0;
                while i < h.len() {
                    if h.len() - i < dl {
                        if l {
                            return Ok(flush(i));
                        }
                        return Ok(flush(h.len()));
                    }
                    if &h[i..i + dl] == &delim[..] {
                        return Ok(pop(i, dl, None));
                    }
                    i += 1;
                }
                Ok(flush(h.len()))
            }
            Sit::Test { trig } => Ok(test(*trig, h, l)),
            Sit::TestN { trig, insert, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, h, 0, l) {
                        if wn.is_push() {
                            return Ok(wn);
                        }
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                Ok(replace(0, 0, a(insert), Sit::Arg { trig: *trig }))
            }
            Sit::TestX { trig, op_len, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, h, 0, l) {
                        if wn.is_push() {
                            return Ok(wn);
                        }
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                let n = 2 + *op_len;
                let after = n + 1;
                if after >= h.len() && l {
                    return Ok(flush(0));
                }
                let alt: &[u8] = if after >= h.len() || !is_word(h[after]) { b"\"\"" } else { b"" };
                Ok(replace(n, 1, a(alt), Sit::Arg { trig: *trig }))
            }
            Sit::For { trig } => Ok(for_(*trig, h, l)),
            Sit::ForArr { phase, pre } => match *phase {
                0 => {
                    *phase = 1;
                    Ok(flush_alt(*pre, 0, a(b"\"")))
                }
                1 => {
                    *phase = 2;
                    Ok(push(0, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"[@]}") }))
                }
                _ => Ok(pop(0, 0, a(b"\""))),
            },
            Sit::CaseSubj => Ok(case_subj(h, l)),
            Sit::CaseBody => Ok(case_body(h, l)),
            Sit::CasePattern => {
                for i in 0..h.len() {
                    if h[i] == b')' {
                        return Ok(replace(i, 1, None, Sit::Normal { trig: Trig::CaseItem, end_alt: None }));
                    }
                    if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
                        return Ok(wn);
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Pitfall { len } => Err(SynErr::Pitfall { pos: 0, len: *len }),
        }
    }
}

fn esc_extent() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_ESC, end_alt: None }
}

fn extent0(color: Color) -> Sit {
    Sit::Extent { rem: 0, color, end_alt: None }
}

fn var_extent2() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_VAR, end_alt: None }
}

pub fn root() -> Sit {
    Sit::Normal { trig: Trig::None, end_alt: None }
}

// ---------------------------------------------------------------- command start

fn normal(trig: Trig, end_alt: &mut Option<Vec<u8>>, h: &[u8], l: bool) -> PResult {
    for i in 0..h.len() {
        let c = h[i];
        if trig == Trig::CaseItem && c == b';' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(flush(i));
                }
            } else if h[i + 1] == b';' {
                return Ok(pop(i, 2, None));
            }
        }
        if is_ws(c) || matches!(c, b';' | b'|' | b'&' | b'<' | b'>') {
            continue;
        }
        if trig == Trig::Paren && c == b')' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if trig == Trig::Backtick && c == b'`' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if c == b'\\' {
            return Ok(push(i, 0, None, esc_extent()));
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        return Ok(keyword_or_command(trig, h, i, l));
    }
    if trig == Trig::None {
        Ok(flush_or_pop(h.len()))
    } else {
        Ok(flush(h.len()))
    }
}

/// Some((name_len, op_len)) = Yes, None + bool maybe.
fn find_lvalue(h: &[u8]) -> (Tri, usize, usize) {
    let n = identlen(h);
    if n == 0 {
        return (Tri::No, 0, 0);
    }
    let mut j = n;
    if j >= h.len() {
        return (Tri::Maybe, 0, 0);
    }
    if h[j] == b'[' {
        match h[j..].iter().position(|&c| c == b']') {
            None => return (Tri::Maybe, 0, 0),
            Some(close) => j += close + 1,
        }
    }
    if j >= h.len() {
        return (Tri::Maybe, 0, 0);
    }
    match h[j] {
        b'=' => (Tri::Yes, j, 1),
        b'+' => {
            if j + 1 >= h.len() {
                (Tri::Maybe, 0, 0)
            } else if h[j + 1] == b'=' {
                (Tri::Yes, j, 2)
            } else {
                (Tri::No, 0, 0)
            }
        }
        _ => (Tri::No, 0, 0),
    }
}

pub fn keyword_or_command(trig: Trig, h: &[u8], i: usize, l: bool) -> WhatNow {
    let c = h[i];
    if c == b'(' {
        if i + 1 >= h.len() {
            if i > 0 || l {
                return flush(i);
            }
        } else if h[i + 1] == b'(' {
            return push(i, 1, None, Sit::Magic { end: b')' });
        }
        return push(i, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None });
    }
    let (found, name_len, op_len) = find_lvalue(&h[i..]);
    if found == Tri::Maybe && (i > 0 || l) {
        return flush(i);
    }
    if found == Tri::Yes {
        return push(i, 0, None, Sit::Lvalue { trig, name_len, op_len });
    }
    let len = predlen(is_word, &h[i..]);
    if i + len == h.len() && (i > 0 || l) {
        return flush(i);
    }
    let word = &h[i..i + len];
    if trig == Trig::CaseItem && word == b"esac" {
        return pop(i, 0, a(b";; "));
    }
    match word {
        b"[[" => push(i, 1, None, Sit::Magic { end: b']' }),
        b"case" => push(i, len, None, Sit::CaseSubj),
        b"for" | b"select" => push(i, len, None, Sit::For { trig }),
        b"!" | b"declare" | b"do" | b"done" | b"elif" | b"else" | b"export" | b"fi" | b"function" | b"if"
        | b"local" | b"readonly" | b"then" | b"until" | b"while" | b"{" | b"}" => {
            push(i, len, None, extent0(COLOR_KWD))
        }
        b"[" | b"test" => {
            if i + len + 1 >= h.len() && (i > 0 || l) {
                return flush(i);
            }
            if h.get(i + len) == Some(&b' ') && h.get(i + len + 1) != Some(&b' ') {
                push(i, len + 1, None, Sit::Test { trig })
            } else {
                push(i, 0, None, Sit::Cmd { trig })
            }
        }
        _ => push(i, 0, None, Sit::Cmd { trig }),
    }
}

/// Handles `>&` (returns Some(skip)) or needs more input.
fn redirect_amp(h: &[u8], i: usize, l: bool) -> Result<bool, WhatNow> {
    if h[i] != b'>' {
        return Ok(false);
    }
    if i + 1 >= h.len() {
        if i > 0 || l {
            return Err(flush(i));
        }
        return Ok(false);
    }
    Ok(h[i + 1] == b'&')
}

fn cmd(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if is_ws(c) {
            return replace(i, 0, None, Sit::Arg { trig });
        }
        if c == b'(' {
            return replace(i, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None });
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn arg(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn rvalue(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if is_ws(c) || matches!(c, b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if c == b'(' {
            return push(i, 1, None, Sit::Vec);
        }
        if let Some(wn) = common_token(Ctx::NoQuote, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn vec_(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b')' {
            return pop(i, 1, None);
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        if let Some(wn) = common_token(Ctx::Arg, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn dq(fresh: bool, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b'"' {
            return pop(i, 1, None);
        }
        if c == b'\\' {
            return push(i, 0, None, esc_extent());
        }
        if c == b'$' || c == b'`' {
            if let Some(wn) = common_token(Ctx::Dq { fresh: fresh && i == 0 }, Trig::None, h, i, l) {
                return wn;
            }
        }
    }
    flush(h.len())
}

fn phantom(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let m = predlen(is_phantomfood, h);
    let close = pop(0, 0, a(b"\""));
    if m == h.len() {
        if l {
            return flush(0);
        }
        return close;
    }
    if h[m] == b'"' {
        return replace(m, 1, a(b""), Sit::Dq { fresh: true });
    }
    if is_end_trig(trig, h[m]) {
        return close;
    }
    match common_token(Ctx::Phantom, trig, h, m, l) {
        Some(wn) => {
            if wn.is_flush() {
                if l {
                    return flush(0);
                }
                return close;
            }
            wn
        }
        None => close,
    }
}

fn magic(end: u8, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == end {
            return pop(i, 1, None);
        }
        if c == b'(' {
            return push(i, 1, None, Sit::Magic { end: b')' });
        }
        if c == b'[' {
            return push(i, 1, None, Sit::Magic { end: b']' });
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn varbrace_sit(
    end_alt: &mut Option<Vec<u8>>,
    depth: &mut usize,
    star: &mut Option<usize>,
    h: &[u8],
    l: bool,
) -> PResult {
    let mut i = 0;
    while i < h.len() {
        if *star == Some(i) {
            *star = None;
            return Ok(flush_alt(i, 1, a(b"@")));
        }
        let c = h[i];
        if c == b'\\' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(adjust_star(star, flush(i)));
                }
            }
            i += 2;
            continue;
        }
        if c == b'$' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(adjust_star(star, flush(i)));
                }
            } else if h[i + 1] == b'{' {
                *depth += 1;
                i += 2;
                continue;
            }
        }
        if c == b'}' {
            if *depth == 0 {
                return Ok(pop(i, 1, end_alt.take()));
            }
            *depth -= 1;
        }
        i += 1;
    }
    Ok(adjust_star(star, flush(h.len())))
}

fn adjust_star(star: &mut Option<usize>, wn: WhatNow) -> WhatNow {
    if let Some(s) = star {
        *s -= wn.pre.min(*s);
    }
    wn
}

// ---------------------------------------------------------------- tokens

/// Handles quotes, escapes, expansions and heredocs at position i of the horizon.
pub fn common_token(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let c = h[i];
    let full = matches!(ctx, Ctx::Arg | Ctx::NoQuote);
    match c {
        b'\'' if full => Some(push(i, 1, None, Sit::Sq)),
        b'"' if full => Some(push(i, 1, None, Sit::Dq { fresh: true })),
        b'\\' if full => Some(push(i, 0, None, esc_extent())),
        b'<' if full => heredoc(h, i, l),
        b'`' => Some(backtick(ctx, trig, h, i, l)),
        b'$' => dollar(ctx, trig, h, i, l),
        _ => None,
    }
}

fn heredoc(h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let need = i > 0 || l;
    if i + 1 >= h.len() {
        return if need { Some(flush(i)) } else { None };
    }
    if h[i + 1] != b'<' {
        return None;
    }
    if i + 2 >= h.len() {
        if need {
            return Some(flush(i));
        }
    } else if h[i + 2] == b'<' {
        return Some(flush(i + 3));
    }
    let fail = if need { Some(flush(i)) } else { Some(flush(i + 2)) };
    let mut j = i + 2;
    if h.get(j) == Some(&b'-') {
        j += 1;
    }
    while j < h.len() && is_ws(h[j]) {
        j += 1;
    }
    let mut delim: Vec<u8> = Vec::new();
    loop {
        if j >= h.len() {
            return fail;
        }
        let c = h[j];
        if is_ws(c) {
            break;
        }
        match c {
            b'\'' => {
                let close = h[j + 1..].iter().position(|&x| x == b'\'');
                match close {
                    None => return fail,
                    Some(k) => {
                        delim.extend_from_slice(&h[j + 1..j + 1 + k]);
                        j += k + 2;
                    }
                }
            }
            b'"' => {
                j += 1;
                loop {
                    if j >= h.len() {
                        return fail;
                    }
                    let d = h[j];
                    if d == b'"' {
                        j += 1;
                        break;
                    }
                    if d == b'\\' {
                        if j + 1 >= h.len() {
                            return fail;
                        }
                        let e = h[j + 1];
                        match e {
                            b'"' | b'\\' | b'$' | b'`' => delim.push(e),
                            b'\n' => {}
                            _ => {
                                delim.push(d);
                                delim.push(e);
                            }
                        }
                        j += 2;
                        continue;
                    }
                    delim.push(d);
                    j += 1;
                }
            }
            b'\\' => {
                if j + 1 >= h.len() {
                    return fail;
                }
                if h[j + 1] != b'\n' {
                    delim.push(h[j + 1]);
                }
                j += 2;
            }
            _ => {
                delim.push(c);
                j += 1;
            }
        }
    }
    if delim.is_empty() {
        return Some(flush(j));
    }
    Some(push(i, j - i, None, Sit::Heredoc { delim }))
}

/// `$(pwd)` or `` `pwd` `` at i (n bytes): replace by $PWD.
fn pwd(ctx: Ctx, h: &[u8], i: usize, n: usize, is_backtick: bool, l: bool) -> Option<WhatNow> {
    let alt: &[u8] = match braces_needed_after(h, i + n) {
        Tri::Maybe => {
            if i > 0 || l {
                return Some(flush(i));
            }
            return None;
        }
        Tri::Yes => {
            if is_backtick && ctx == Ctx::NoQuote {
                return None;
            }
            b"${PWD}"
        }
        Tri::No => b"$PWD",
    };
    Some(push(i, n, a(alt), extent0(COLOR_VAR)))
}

fn backtick(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> WhatNow {
    if ctx == Ctx::Arg {
        return push(i, 0, a(b"\""), Sit::Phantom { trig });
    }
    if i + 5 > h.len() {
        if i > 0 || l {
            return flush(i);
        }
    } else if &h[i..i + 5] == b"`pwd`" {
        if let Some(wn) = pwd(ctx, h, i, 5, true, l) {
            return wn;
        }
    }
    match ctx {
        Ctx::NoQuote => push(i, 1, None, Sit::Normal { trig: Trig::Backtick, end_alt: None }),
        _ => push(i, 1, a(b"$("), Sit::Normal { trig: Trig::Backtick, end_alt: a(b")") }),
    }
}

fn dollar(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let need = i > 0 || l;
    if i + 1 >= h.len() {
        return if need { Some(flush(i)) } else { None };
    }
    let c = h[i + 1];
    if c.is_ascii_digit() && h.get(i + 2).map_or(false, |d| d.is_ascii_digit()) {
        let len = 1 + predlen(|x| x.is_ascii_digit(), &h[i + 1..]);
        return Some(push(i, 0, None, Sit::Pitfall { len }));
    }
    if ctx == Ctx::Arg {
        let phantom = Some(push(i, 0, a(b"\""), Sit::Phantom { trig }));
        return match c {
            b'(' => {
                if i + 2 >= h.len() {
                    if need {
                        return Some(flush(i));
                    }
                    return phantom;
                }
                if h[i + 2] == b'(' {
                    Some(push(i, 2, None, Sit::Magic { end: b')' }))
                } else {
                    phantom
                }
            }
            b'{' => {
                if i + 2 >= h.len() {
                    if need {
                        return Some(flush(i));
                    }
                    return phantom;
                }
                if matches!(h[i + 2], b'#' | b'!') {
                    Some(push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None }))
                } else {
                    phantom
                }
            }
            b'\'' => Some(push(i, 2, None, Sit::SqEsc)),
            b'*' => Some(push(i, 0, a(b"\""), Sit::StarPhantom { phase: 0 })),
            b'@' | b'-' => phantom,
            b'?' | b'$' | b'!' | b'#' => Some(push(i, 0, None, var_extent2())),
            _ if c.is_ascii_digit() || is_identhead(c) => phantom,
            _ => None,
        };
    }
    match c {
        b'(' => {
            if i + 2 >= h.len() {
                if need {
                    return Some(flush(i));
                }
                return Some(push(i, 2, None, Sit::Normal { trig: Trig::Paren, end_alt: None }));
            }
            if h[i + 2] == b'(' {
                return Some(push(i, 2, None, Sit::Magic { end: b')' }));
            }
            if i + 6 > h.len() {
                if need {
                    return Some(flush(i));
                }
            } else if &h[i..i + 6] == b"$(pwd)" {
                if let Some(wn) = pwd(ctx, h, i, 6, false, l) {
                    return Some(wn);
                }
            }
            Some(push(i, 2, None, Sit::Normal { trig: Trig::Paren, end_alt: None }))
        }
        b'{' => Some(varbrace(ctx, h, i, l)),
        b'\'' => {
            if ctx == Ctx::NoQuote {
                Some(push(i, 2, None, Sit::SqEsc))
            } else {
                None
            }
        }
        b'*' | b'@' | b'-' | b'?' | b'$' | b'!' | b'#' => Some(push(i, 0, None, var_extent2())),
        _ if c.is_ascii_digit() => Some(push(i, 0, None, var_extent2())),
        _ if is_identhead(c) => {
            if ctx == Ctx::Phantom {
                let n = predlen(is_identtail, &h[i + 1..]);
                match braces_needed_after(h, i + 1 + n) {
                    Tri::Maybe => {
                        if need {
                            return Some(flush(i));
                        }
                        return Some(push(i, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"}") }));
                    }
                    Tri::Yes => return Some(push(i, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"}") })),
                    Tri::No => {}
                }
            }
            Some(push(i, 1, None, Sit::VarIdent { end_alt: None }))
        }
        _ => None,
    }
}

fn varbrace(ctx: Ctx, h: &[u8], i: usize, l: bool) -> WhatNow {
    let need = i > 0 || l;
    let keep = push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None });
    let remove = push(i, 2, a(b"$"), Sit::VarBrace { end_alt: a(b""), depth: 0, star: None });
    let n = identlen(&h[i + 2..]);
    let j = i + 2 + n;
    match ctx {
        Ctx::Phantom => {
            if n == 0 {
                if i + 2 >= h.len() && need {
                    return flush(i);
                }
                return keep;
            }
            if j >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j] == b'}' {
                return match braces_needed_after(h, j + 1) {
                    Tri::Maybe => {
                        if need {
                            flush(i)
                        } else {
                            keep
                        }
                    }
                    Tri::Yes => keep,
                    Tri::No => remove,
                };
            }
            if h[j] == b'[' {
                if j + 3 > h.len() {
                    if need {
                        return flush(i);
                    }
                    return keep;
                }
                if &h[j..j + 3] == b"[*]" {
                    return push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: Some(n + 1) });
                }
            }
            keep
        }
        Ctx::Dq { fresh: true } => {
            if n == 0 {
                if i + 2 >= h.len() && need {
                    return flush(i);
                }
                return keep;
            }
            if j >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j] != b'}' {
                return keep;
            }
            if j + 1 >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j + 1] != b'"' {
                return keep;
            }
            match braces_needed_after(h, j + 1) {
                Tri::Maybe => {
                    if need {
                        flush(i)
                    } else {
                        keep
                    }
                }
                Tri::Yes => keep,
                Tri::No => remove,
            }
        }
        _ => keep,
    }
}

// ---------------------------------------------------------------- test

fn test(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    if h.len() < 4 && l {
        return flush(0);
    }
    if h.starts_with(b"-n ") || h.starts_with(b"-z ") {
        if h.len() > 3 {
            if let Some(wn) = common_token(Ctx::Arg, trig, h, 3, l) {
                if wn.is_flush() {
                    if l {
                        return flush(0);
                    }
                } else if wn.is_push() {
                    let insert: &'static [u8] = if h[1] == b'n' { b" != \"\"" } else { b" = \"\"" };
                    return replace(0, 3, a(b""), Sit::TestN { trig, insert, started: false });
                }
            }
        }
    }
    if h.first() == Some(&b'x') && h.len() > 1 {
        if let Some(wn) = common_token(Ctx::Arg, trig, h, 1, l) {
            if wn.is_flush() {
                if l {
                    return flush(0);
                }
            } else if wn.is_push() {
                if let Some(end) = crate::machine::simulate_token(h, wn, trig, l) {
                    let r = &h[end..];
                    let op_len = if r.starts_with(b" = x") {
                        Some(1)
                    } else if r.starts_with(b" == x") || r.starts_with(b" != x") {
                        Some(2)
                    } else {
                        if r.len() < 5 && l {
                            return flush(0);
                        }
                        None
                    };
                    if let Some(op_len) = op_len {
                        return replace(0, 1, a(b""), Sit::TestX { trig, op_len, started: false });
                    }
                }
            }
        }
    }
    replace(0, 0, None, Sit::Arg { trig })
}

// ---------------------------------------------------------------- for

fn for_(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b'\n' || c == b';' {
            return pop(i, 0, None);
        }
        if is_ws(c) {
            continue;
        }
        if is_identhead(c) {
            let n = identlen(&h[i..]);
            if i + n == h.len() && (i > 0 || l) {
                return flush(i);
            }
            if &h[i..i + n] == b"in" {
                match for_special(&h[i..]) {
                    Tri::Maybe => {
                        if i > 0 || l {
                            return flush(i);
                        }
                    }
                    Tri::Yes => {
                        let pre = for_special_pre(&h[i..]);
                        return push(i, 0, None, Sit::ForArr { phase: 0, pre });
                    }
                    Tri::No => {}
                }
                return push(i, 0, None, Sit::Arg { trig });
            }
            return push(i, n, None, extent0(COLOR_LVAR));
        }
        let wn = keyword_or_command(trig, h, i, l);
        return match wn.tr {
            Tr::Push(s) => WhatNow { tr: Tr::Replace(s), pre: wn.pre, len: wn.len, alt: wn.alt },
            other => WhatNow { tr: other, pre: wn.pre, len: wn.len, alt: wn.alt },
        };
    }
    flush(h.len())
}

fn for_special_pre(h: &[u8]) -> usize {
    let mut j = 2;
    while j < h.len() && (h[j] == b' ' || h[j] == b'\t') {
        j += 1;
    }
    j
}

/// `in` + whitespace + `$ident` + spaces + (`;` | newline).
fn for_special(h: &[u8]) -> Tri {
    let j0 = for_special_pre(h);
    if j0 >= h.len() {
        return Tri::Maybe;
    }
    if j0 == 2 {
        return Tri::No;
    }
    let mut j = j0;
    if h[j] != b'$' {
        return Tri::No;
    }
    j += 1;
    if j >= h.len() {
        return Tri::Maybe;
    }
    let n = identlen(&h[j..]);
    if n == 0 {
        return Tri::No;
    }
    j += n;
    while j < h.len() && h[j] == b' ' {
        j += 1;
    }
    match h.get(j) {
        None => Tri::Maybe,
        Some(b';') | Some(b'\n') => Tri::Yes,
        _ => Tri::No,
    }
}

// ---------------------------------------------------------------- case

fn case_subj(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            let r = &h[i + 1..];
            if r.len() < 3 && (i > 0 || l) {
                if b"in".starts_with(&r[..r.len().min(2)]) {
                    return flush(i);
                }
            }
            if r.starts_with(b"in") && r.get(2).map_or(true, |&d| !is_word(d)) {
                return replace(i + 3, 0, None, Sit::CaseBody);
            }
            continue;
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn case_body(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            continue;
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        let len = predlen(is_word, &h[i..]);
        if i + len == h.len() && (i > 0 || l) {
            return flush(i);
        }
        if &h[i..i + len] == b"esac" {
            return replace(i, 4, None, extent0(COLOR_KWD));
        }
        return push(i, 0, None, Sit::CasePattern);
    }
    flush(h.len())
}
EOF
echo done"}

actions.command:
cat > /workspace/src/sit.rs <<'EOF'
// Situations of the parser state machine. Each situation looks at a horizon
// (a window of upcoming input) and decides what to do next.

pub type Color = u32;
pub const BOLD: u32 = 1 << 24;
pub const ITAL: u32 = 1 << 25;
pub const COLOR_NORMAL: Color = 0;
pub const COLOR_KWD: Color = BOLD;
pub const COLOR_CMD: Color = 0xc00080;
pub const COLOR_VAR: Color = 0x3f7fcf;
pub const COLOR_LVAR: Color = 0x007fff;
pub const COLOR_DQ: Color = 0xff0000;
pub const COLOR_SQ: Color = 0xffcc55;
pub const COLOR_SQESC: Color = 0xff8000;
pub const COLOR_ESC: Color = 0xff0080 | BOLD;
pub const COLOR_CMT: Color = 0x789060 | BOLD | ITAL;
pub const COLOR_HERE: Color = 0x802000;
pub const COLOR_MAGIC: Color = 0xc000c0;

#[derive(Debug)]
pub enum SynErr {
    Eof,
    /// Position relative to the start of the horizon given to whatnow, length.
    Pitfall { pos: usize, len: usize },
}

pub type PResult = Result<WhatNow, SynErr>;

pub enum Tr {
    Flush,
    FlushPopOnEof,
    Replace(Sit),
    Push(Sit),
    Pop,
}

pub struct WhatNow {
    pub tr: Tr,
    pub pre: usize,
    pub len: usize,
    pub alt: Option<Vec<u8>>,
}

impl WhatNow {
    pub fn is_push(&self) -> bool {
        matches!(self.tr, Tr::Push(_))
    }
    pub fn is_flush(&self) -> bool {
        matches!(self.tr, Tr::Flush | Tr::FlushPopOnEof)
    }
}

fn a(s: &[u8]) -> Option<Vec<u8>> {
    Some(s.to_vec())
}

pub fn flush(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len: 0, alt: None }
}
pub fn flush_alt(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Flush, pre, len, alt }
}
pub fn flush_or_pop(pre: usize) -> WhatNow {
    WhatNow { tr: Tr::FlushPopOnEof, pre, len: 0, alt: None }
}
pub fn push(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Push(s), pre, len, alt }
}
pub fn replace(pre: usize, len: usize, alt: Option<Vec<u8>>, s: Sit) -> WhatNow {
    WhatNow { tr: Tr::Replace(s), pre, len, alt }
}
pub fn pop(pre: usize, len: usize, alt: Option<Vec<u8>>) -> WhatNow {
    WhatNow { tr: Tr::Pop, pre, len, alt }
}

// ---------------------------------------------------------------- predicates

pub fn is_ws(c: u8) -> bool {
    c <= b' '
}
pub fn is_identhead(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphabetic()
}
pub fn is_identtail(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphanumeric()
}
pub fn is_word(c: u8) -> bool {
    !(c <= b' ' || matches!(c, b';' | b'&' | b'|' | b'<' | b'>' | b'(' | b')' | b'`'))
}
pub fn is_phantomfood(c: u8) -> bool {
    c >= b'+' && !matches!(c, b';' | b'<' | b'>' | b'?' | b'\\' | b'`' | b'|')
}
pub fn predlen(f: fn(u8) -> bool, h: &[u8]) -> usize {
    h.iter().take_while(|&&c| f(c)).count()
}
fn identlen(h: &[u8]) -> usize {
    if h.is_empty() || !is_identhead(h[0]) {
        return 0;
    }
    predlen(is_identtail, h)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Tri {
    No,
    Yes,
    Maybe,
}

/// After position j, skip double quotes; are braces needed (identifier tail follows)?
/// Maybe if the horizon ends.
fn braces_needed_after(h: &[u8], mut j: usize) -> Tri {
    while j < h.len() && h[j] == b'"' {
        j += 1;
    }
    if j >= h.len() {
        Tri::Maybe
    } else if is_identtail(h[j]) {
        Tri::Yes
    } else {
        Tri::No
    }
}

// ---------------------------------------------------------------- triggers & contexts

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Trig {
    None,
    Paren,
    Backtick,
    CaseItem,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ctx {
    /// Unquoted argument context: expansions need quotes.
    Arg,
    /// Inside a phantom (inserted) double-quoted string.
    Phantom,
    /// Inside a real double-quoted string. `fresh` = at the very start of it.
    Dq { fresh: bool },
    /// Quoting is not needed (assignment, [[ ]], case ...).
    NoQuote,
}

fn is_end_trig(trig: Trig, c: u8) -> bool {
    (trig == Trig::Paren && c == b')') || (trig == Trig::Backtick && c == b'`')
}

// ---------------------------------------------------------------- situations

#[derive(Clone, Debug)]
pub enum Sit {
    Normal { trig: Trig, end_alt: Option<Vec<u8>> },
    Cmd { trig: Trig },
    Arg { trig: Trig },
    Lvalue { trig: Trig, name_len: usize, op_len: usize },
    Rvalue { trig: Trig },
    Vec,
    Dq { fresh: bool },
    Phantom { trig: Trig },
    StarPhantom { phase: u8 },
    Sq,
    SqEsc,
    Extent { rem: usize, color: Color, end_alt: Option<Vec<u8>> },
    VarIdent { end_alt: Option<Vec<u8>> },
    VarBrace { end_alt: Option<Vec<u8>>, depth: usize, star: Option<usize> },
    Magic { end: u8 },
    Comment,
    Heredoc { delim: Vec<u8> },
    Test { trig: Trig },
    TestN { trig: Trig, insert: &'static [u8], started: bool },
    TestX { trig: Trig, op_len: usize, started: bool },
    For { trig: Trig },
    ForArr { phase: u8, pre: usize },
    CaseSubj,
    CaseBody,
    CasePattern,
    Pitfall { len: usize },
}

impl Sit {
    pub fn color(&self) -> Color {
        match self {
            Sit::Normal { .. } => COLOR_NORMAL,
            Sit::Cmd { .. } => COLOR_CMD,
            Sit::Arg { .. } => COLOR_NORMAL,
            Sit::Lvalue { .. } => COLOR_LVAR,
            Sit::Rvalue { .. } => COLOR_NORMAL,
            Sit::Vec => COLOR_NORMAL,
            Sit::Dq { .. } => COLOR_DQ,
            Sit::Phantom { .. } => COLOR_DQ,
            Sit::StarPhantom { .. } => COLOR_VAR,
            Sit::Sq => COLOR_SQ,
            Sit::SqEsc => COLOR_SQESC,
            Sit::Extent { color, .. } => *color,
            Sit::VarIdent { .. } => COLOR_VAR,
            Sit::VarBrace { .. } => COLOR_VAR,
            Sit::Magic { .. } => COLOR_MAGIC,
            Sit::Comment => COLOR_CMT,
            Sit::Heredoc { .. } => COLOR_HERE,
            Sit::Test { .. } => COLOR_CMD,
            Sit::TestN { .. } => COLOR_NORMAL,
            Sit::TestX { .. } => COLOR_NORMAL,
            Sit::For { .. } => COLOR_KWD,
            Sit::ForArr { .. } => COLOR_NORMAL,
            Sit::CaseSubj => COLOR_KWD,
            Sit::CaseBody => COLOR_NORMAL,
            Sit::CasePattern => COLOR_NORMAL,
            Sit::Pitfall { .. } => COLOR_NORMAL,
        }
    }

    pub fn whatnow(&mut self, h: &[u8], l: bool) -> PResult {
        match self {
            Sit::Normal { trig, end_alt } => normal(*trig, end_alt, h, l),
            Sit::Cmd { trig } => Ok(cmd(*trig, h, l)),
            Sit::Arg { trig } => Ok(arg(*trig, h, l)),
            Sit::Lvalue { trig, name_len, op_len } => {
                Ok(replace(*name_len, *op_len, None, Sit::Rvalue { trig: *trig }))
            }
            Sit::Rvalue { trig } => Ok(rvalue(*trig, h, l)),
            Sit::Vec => Ok(vec_(h, l)),
            Sit::Dq { fresh } => {
                let wn = dq(*fresh, h, l);
                if !(wn.is_flush() && wn.pre == 0 && wn.len == 0) {
                    *fresh = false;
                }
                Ok(wn)
            }
            Sit::Phantom { trig } => Ok(phantom(*trig, h, l)),
            Sit::StarPhantom { phase } => {
                if *phase == 0 {
                    *phase = 1;
                    Ok(flush_alt(0, 2, a(b"$@")))
                } else {
                    Ok(pop(0, 0, a(b"\"")))
                }
            }
            Sit::Sq => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::SqEsc => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\'' {
                        return Ok(pop(i, 1, None));
                    }
                    if c == b'\\' {
                        return Ok(push(i, 0, None, esc_extent()));
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Extent { rem, end_alt, .. } => {
                if h.len() >= *rem {
                    Ok(pop(*rem, 0, end_alt.take()))
                } else {
                    *rem -= h.len();
                    Ok(flush(h.len()))
                }
            }
            Sit::VarIdent { end_alt } => {
                let n = predlen(is_identtail, h);
                if n == h.len() && l {
                    return Ok(flush(n));
                }
                Ok(pop(n, 0, end_alt.take()))
            }
            Sit::VarBrace { end_alt, depth, star } => varbrace_sit(end_alt, depth, star, h, l),
            Sit::Magic { end } => Ok(magic(*end, h, l)),
            Sit::Comment => {
                for (i, &c) in h.iter().enumerate() {
                    if c == b'\n' {
                        return Ok(pop(i, 0, None));
                    }
                }
                Ok(flush_or_pop(h.len()))
            }
            Sit::Heredoc { delim } => {
                let dl = delim.len();
                let mut i = 0;
                while i < h.len() {
                    if h.len() - i < dl {
                        if l {
                            return Ok(flush(i));
                        }
                        return Ok(flush(h.len()));
                    }
                    if &h[i..i + dl] == &delim[..] {
                        return Ok(pop(i, dl, None));
                    }
                    i += 1;
                }
                Ok(flush(h.len()))
            }
            Sit::Test { trig } => Ok(test(*trig, h, l)),
            Sit::TestN { trig, insert, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, h, 0, l) {
                        if wn.is_push() {
                            return Ok(wn);
                        }
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                Ok(replace(0, 0, a(insert), Sit::Arg { trig: *trig }))
            }
            Sit::TestX { trig, op_len, started } => {
                if !*started {
                    *started = true;
                    if let Some(wn) = common_token(Ctx::Arg, *trig, h, 0, l) {
                        if wn.is_push() {
                            return Ok(wn);
                        }
                    }
                    return Ok(replace(0, 0, None, Sit::Arg { trig: *trig }));
                }
                let n = 2 + *op_len;
                let after = n + 1;
                if after >= h.len() && l {
                    return Ok(flush(0));
                }
                let alt: &[u8] = if after >= h.len() || !is_word(h[after]) { b"\"\"" } else { b"" };
                Ok(replace(n, 1, a(alt), Sit::Arg { trig: *trig }))
            }
            Sit::For { trig } => Ok(for_(*trig, h, l)),
            Sit::ForArr { phase, pre } => match *phase {
                0 => {
                    *phase = 1;
                    Ok(flush_alt(*pre, 0, a(b"\"")))
                }
                1 => {
                    *phase = 2;
                    Ok(push(0, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"[@]}") }))
                }
                _ => Ok(pop(0, 0, a(b"\""))),
            },
            Sit::CaseSubj => Ok(case_subj(h, l)),
            Sit::CaseBody => Ok(case_body(h, l)),
            Sit::CasePattern => {
                for i in 0..h.len() {
                    if h[i] == b')' {
                        return Ok(replace(i, 1, None, Sit::Normal { trig: Trig::CaseItem, end_alt: None }));
                    }
                    if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
                        return Ok(wn);
                    }
                }
                Ok(flush(h.len()))
            }
            Sit::Pitfall { len } => Err(SynErr::Pitfall { pos: 0, len: *len }),
        }
    }
}

fn esc_extent() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_ESC, end_alt: None }
}

fn extent0(color: Color) -> Sit {
    Sit::Extent { rem: 0, color, end_alt: None }
}

fn var_extent2() -> Sit {
    Sit::Extent { rem: 2, color: COLOR_VAR, end_alt: None }
}

pub fn root() -> Sit {
    Sit::Normal { trig: Trig::None, end_alt: None }
}

// ---------------------------------------------------------------- command start

fn normal(trig: Trig, end_alt: &mut Option<Vec<u8>>, h: &[u8], l: bool) -> PResult {
    for i in 0..h.len() {
        let c = h[i];
        if trig == Trig::CaseItem && c == b';' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(flush(i));
                }
            } else if h[i + 1] == b';' {
                return Ok(pop(i, 2, None));
            }
        }
        if is_ws(c) || matches!(c, b';' | b'|' | b'&' | b'<' | b'>') {
            continue;
        }
        if trig == Trig::Paren && c == b')' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if trig == Trig::Backtick && c == b'`' {
            return Ok(pop(i, 1, end_alt.take()));
        }
        if c == b'\\' {
            return Ok(push(i, 0, None, esc_extent()));
        }
        if c == b'#' {
            return Ok(push(i, 0, None, Sit::Comment));
        }
        return Ok(keyword_or_command(trig, h, i, l));
    }
    if trig == Trig::None {
        Ok(flush_or_pop(h.len()))
    } else {
        Ok(flush(h.len()))
    }
}

/// Some((name_len, op_len)) = Yes, None + bool maybe.
fn find_lvalue(h: &[u8]) -> (Tri, usize, usize) {
    let n = identlen(h);
    if n == 0 {
        return (Tri::No, 0, 0);
    }
    let mut j = n;
    if j >= h.len() {
        return (Tri::Maybe, 0, 0);
    }
    if h[j] == b'[' {
        match h[j..].iter().position(|&c| c == b']') {
            None => return (Tri::Maybe, 0, 0),
            Some(close) => j += close + 1,
        }
    }
    if j >= h.len() {
        return (Tri::Maybe, 0, 0);
    }
    match h[j] {
        b'=' => (Tri::Yes, j, 1),
        b'+' => {
            if j + 1 >= h.len() {
                (Tri::Maybe, 0, 0)
            } else if h[j + 1] == b'=' {
                (Tri::Yes, j, 2)
            } else {
                (Tri::No, 0, 0)
            }
        }
        _ => (Tri::No, 0, 0),
    }
}

pub fn keyword_or_command(trig: Trig, h: &[u8], i: usize, l: bool) -> WhatNow {
    let c = h[i];
    if c == b'(' {
        if i + 1 >= h.len() {
            if i > 0 || l {
                return flush(i);
            }
        } else if h[i + 1] == b'(' {
            return push(i, 1, None, Sit::Magic { end: b')' });
        }
        return push(i, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None });
    }
    let (found, name_len, op_len) = find_lvalue(&h[i..]);
    if found == Tri::Maybe && (i > 0 || l) {
        return flush(i);
    }
    if found == Tri::Yes {
        return push(i, 0, None, Sit::Lvalue { trig, name_len, op_len });
    }
    let len = predlen(is_word, &h[i..]);
    if i + len == h.len() && (i > 0 || l) {
        return flush(i);
    }
    let word = &h[i..i + len];
    if trig == Trig::CaseItem && word == b"esac" {
        return pop(i, 0, a(b";; "));
    }
    match word {
        b"[[" => push(i, 1, None, Sit::Magic { end: b']' }),
        b"case" => push(i, len, None, Sit::CaseSubj),
        b"for" | b"select" => push(i, len, None, Sit::For { trig }),
        b"!" | b"declare" | b"do" | b"done" | b"elif" | b"else" | b"export" | b"fi" | b"function" | b"if"
        | b"local" | b"readonly" | b"then" | b"until" | b"while" | b"{" | b"}" => {
            push(i, len, None, extent0(COLOR_KWD))
        }
        b"[" | b"test" => {
            if i + len + 1 >= h.len() && (i > 0 || l) {
                return flush(i);
            }
            if h.get(i + len) == Some(&b' ') && h.get(i + len + 1) != Some(&b' ') {
                push(i, len + 1, None, Sit::Test { trig })
            } else {
                push(i, 0, None, Sit::Cmd { trig })
            }
        }
        _ => push(i, 0, None, Sit::Cmd { trig }),
    }
}

/// Handles `>&` (returns Some(skip)) or needs more input.
fn redirect_amp(h: &[u8], i: usize, l: bool) -> Result<bool, WhatNow> {
    if h[i] != b'>' {
        return Ok(false);
    }
    if i + 1 >= h.len() {
        if i > 0 || l {
            return Err(flush(i));
        }
        return Ok(false);
    }
    Ok(h[i + 1] == b'&')
}

fn cmd(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if is_ws(c) {
            return replace(i, 0, None, Sit::Arg { trig });
        }
        if c == b'(' {
            return replace(i, 1, None, Sit::Normal { trig: Trig::Paren, end_alt: None });
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn arg(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if matches!(c, b'\n' | b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        if let Some(wn) = common_token(Ctx::Arg, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn rvalue(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let mut i = 0;
    while i < h.len() {
        let c = h[i];
        match redirect_amp(h, i, l) {
            Err(wn) => return wn,
            Ok(true) => {
                i += 2;
                continue;
            }
            Ok(false) => {}
        }
        if is_ws(c) || matches!(c, b';' | b'|' | b'&') || is_end_trig(trig, c) {
            return pop(i, 0, None);
        }
        if c == b'(' {
            return push(i, 1, None, Sit::Vec);
        }
        if let Some(wn) = common_token(Ctx::NoQuote, trig, h, i, l) {
            return wn;
        }
        i += 1;
    }
    flush_or_pop(h.len())
}

fn vec_(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b')' {
            return pop(i, 1, None);
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        if let Some(wn) = common_token(Ctx::Arg, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn dq(fresh: bool, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b'"' {
            return pop(i, 1, None);
        }
        if c == b'\\' {
            return push(i, 0, None, esc_extent());
        }
        if c == b'$' || c == b'`' {
            if let Some(wn) = common_token(Ctx::Dq { fresh: fresh && i == 0 }, Trig::None, h, i, l) {
                return wn;
            }
        }
    }
    flush(h.len())
}

fn phantom(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    let m = predlen(is_phantomfood, h);
    let close = pop(0, 0, a(b"\""));
    if m == h.len() {
        if l {
            return flush(0);
        }
        return close;
    }
    if h[m] == b'"' {
        return replace(m, 1, a(b""), Sit::Dq { fresh: true });
    }
    if is_end_trig(trig, h[m]) {
        return close;
    }
    match common_token(Ctx::Phantom, trig, h, m, l) {
        Some(wn) => {
            if wn.is_flush() {
                if l {
                    return flush(0);
                }
                return close;
            }
            wn
        }
        None => close,
    }
}

fn magic(end: u8, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == end {
            return pop(i, 1, None);
        }
        if c == b'(' {
            return push(i, 1, None, Sit::Magic { end: b')' });
        }
        if c == b'[' {
            return push(i, 1, None, Sit::Magic { end: b']' });
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn varbrace_sit(
    end_alt: &mut Option<Vec<u8>>,
    depth: &mut usize,
    star: &mut Option<usize>,
    h: &[u8],
    l: bool,
) -> PResult {
    let mut i = 0;
    while i < h.len() {
        if *star == Some(i) {
            *star = None;
            return Ok(flush_alt(i, 1, a(b"@")));
        }
        let c = h[i];
        if c == b'\\' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(adjust_star(star, flush(i)));
                }
            }
            i += 2;
            continue;
        }
        if c == b'$' {
            if i + 1 >= h.len() {
                if i > 0 || l {
                    return Ok(adjust_star(star, flush(i)));
                }
            } else if h[i + 1] == b'{' {
                *depth += 1;
                i += 2;
                continue;
            }
        }
        if c == b'}' {
            if *depth == 0 {
                return Ok(pop(i, 1, end_alt.take()));
            }
            *depth -= 1;
        }
        i += 1;
    }
    Ok(adjust_star(star, flush(h.len())))
}

fn adjust_star(star: &mut Option<usize>, wn: WhatNow) -> WhatNow {
    if let Some(s) = star {
        *s -= wn.pre.min(*s);
    }
    wn
}

// ---------------------------------------------------------------- tokens

/// Handles quotes, escapes, expansions and heredocs at position i of the horizon.
pub fn common_token(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let c = h[i];
    let full = matches!(ctx, Ctx::Arg | Ctx::NoQuote);
    match c {
        b'\'' if full => Some(push(i, 1, None, Sit::Sq)),
        b'"' if full => Some(push(i, 1, None, Sit::Dq { fresh: true })),
        b'\\' if full => Some(push(i, 0, None, esc_extent())),
        b'<' if full => heredoc(h, i, l),
        b'`' => Some(backtick(ctx, trig, h, i, l)),
        b'$' => dollar(ctx, trig, h, i, l),
        _ => None,
    }
}

fn heredoc(h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let need = i > 0 || l;
    if i + 1 >= h.len() {
        return if need { Some(flush(i)) } else { None };
    }
    if h[i + 1] != b'<' {
        return None;
    }
    if i + 2 >= h.len() {
        if need {
            return Some(flush(i));
        }
    } else if h[i + 2] == b'<' {
        return Some(flush(i + 3));
    }
    let fail = if need { Some(flush(i)) } else { Some(flush(i + 2)) };
    let mut j = i + 2;
    if h.get(j) == Some(&b'-') {
        j += 1;
    }
    while j < h.len() && is_ws(h[j]) {
        j += 1;
    }
    let mut delim: Vec<u8> = Vec::new();
    loop {
        if j >= h.len() {
            return fail;
        }
        let c = h[j];
        if is_ws(c) {
            break;
        }
        match c {
            b'\'' => {
                let close = h[j + 1..].iter().position(|&x| x == b'\'');
                match close {
                    None => return fail,
                    Some(k) => {
                        delim.extend_from_slice(&h[j + 1..j + 1 + k]);
                        j += k + 2;
                    }
                }
            }
            b'"' => {
                j += 1;
                loop {
                    if j >= h.len() {
                        return fail;
                    }
                    let d = h[j];
                    if d == b'"' {
                        j += 1;
                        break;
                    }
                    if d == b'\\' {
                        if j + 1 >= h.len() {
                            return fail;
                        }
                        let e = h[j + 1];
                        match e {
                            b'"' | b'\\' | b'$' | b'`' => delim.push(e),
                            b'\n' => {}
                            _ => {
                                delim.push(d);
                                delim.push(e);
                            }
                        }
                        j += 2;
                        continue;
                    }
                    delim.push(d);
                    j += 1;
                }
            }
            b'\\' => {
                if j + 1 >= h.len() {
                    return fail;
                }
                if h[j + 1] != b'\n' {
                    delim.push(h[j + 1]);
                }
                j += 2;
            }
            _ => {
                delim.push(c);
                j += 1;
            }
        }
    }
    if delim.is_empty() {
        return Some(flush(j));
    }
    Some(push(i, j - i, None, Sit::Heredoc { delim }))
}

/// `$(pwd)` or `` `pwd` `` at i (n bytes): replace by $PWD.
fn pwd(ctx: Ctx, h: &[u8], i: usize, n: usize, is_backtick: bool, l: bool) -> Option<WhatNow> {
    let alt: &[u8] = match braces_needed_after(h, i + n) {
        Tri::Maybe => {
            if i > 0 || l {
                return Some(flush(i));
            }
            return None;
        }
        Tri::Yes => {
            if is_backtick && ctx == Ctx::NoQuote {
                return None;
            }
            b"${PWD}"
        }
        Tri::No => b"$PWD",
    };
    Some(push(i, n, a(alt), extent0(COLOR_VAR)))
}

fn backtick(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> WhatNow {
    if ctx == Ctx::Arg {
        return push(i, 0, a(b"\""), Sit::Phantom { trig });
    }
    if i + 5 > h.len() {
        if i > 0 || l {
            return flush(i);
        }
    } else if &h[i..i + 5] == b"`pwd`" {
        if let Some(wn) = pwd(ctx, h, i, 5, true, l) {
            return wn;
        }
    }
    match ctx {
        Ctx::NoQuote => push(i, 1, None, Sit::Normal { trig: Trig::Backtick, end_alt: None }),
        _ => push(i, 1, a(b"$("), Sit::Normal { trig: Trig::Backtick, end_alt: a(b")") }),
    }
}

fn dollar(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> Option<WhatNow> {
    let need = i > 0 || l;
    if i + 1 >= h.len() {
        return if need { Some(flush(i)) } else { None };
    }
    let c = h[i + 1];
    if c.is_ascii_digit() && h.get(i + 2).map_or(false, |d| d.is_ascii_digit()) {
        let len = 1 + predlen(|x| x.is_ascii_digit(), &h[i + 1..]);
        return Some(push(i, 0, None, Sit::Pitfall { len }));
    }
    if ctx == Ctx::Arg {
        let phantom = Some(push(i, 0, a(b"\""), Sit::Phantom { trig }));
        return match c {
            b'(' => {
                if i + 2 >= h.len() {
                    if need {
                        return Some(flush(i));
                    }
                    return phantom;
                }
                if h[i + 2] == b'(' {
                    Some(push(i, 2, None, Sit::Magic { end: b')' }))
                } else {
                    phantom
                }
            }
            b'{' => {
                if i + 2 >= h.len() {
                    if need {
                        return Some(flush(i));
                    }
                    return phantom;
                }
                if matches!(h[i + 2], b'#' | b'!') {
                    Some(push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None }))
                } else {
                    phantom
                }
            }
            b'\'' => Some(push(i, 2, None, Sit::SqEsc)),
            b'*' => Some(push(i, 0, a(b"\""), Sit::StarPhantom { phase: 0 })),
            b'@' | b'-' => phantom,
            b'?' | b'$' | b'!' | b'#' => Some(push(i, 0, None, var_extent2())),
            _ if c.is_ascii_digit() || is_identhead(c) => phantom,
            _ => None,
        };
    }
    match c {
        b'(' => {
            if i + 2 >= h.len() {
                if need {
                    return Some(flush(i));
                }
                return Some(push(i, 2, None, Sit::Normal { trig: Trig::Paren, end_alt: None }));
            }
            if h[i + 2] == b'(' {
                return Some(push(i, 2, None, Sit::Magic { end: b')' }));
            }
            if i + 6 > h.len() {
                if need {
                    return Some(flush(i));
                }
            } else if &h[i..i + 6] == b"$(pwd)" {
                if let Some(wn) = pwd(ctx, h, i, 6, false, l) {
                    return Some(wn);
                }
            }
            Some(push(i, 2, None, Sit::Normal { trig: Trig::Paren, end_alt: None }))
        }
        b'{' => Some(varbrace(ctx, h, i, l)),
        b'\'' => {
            if ctx == Ctx::NoQuote {
                Some(push(i, 2, None, Sit::SqEsc))
            } else {
                None
            }
        }
        b'*' | b'@' | b'-' | b'?' | b'$' | b'!' | b'#' => Some(push(i, 0, None, var_extent2())),
        _ if c.is_ascii_digit() => Some(push(i, 0, None, var_extent2())),
        _ if is_identhead(c) => {
            if ctx == Ctx::Phantom {
                let n = predlen(is_identtail, &h[i + 1..]);
                match braces_needed_after(h, i + 1 + n) {
                    Tri::Maybe => {
                        if need {
                            return Some(flush(i));
                        }
                        return Some(push(i, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"}") }));
                    }
                    Tri::Yes => return Some(push(i, 1, a(b"${"), Sit::VarIdent { end_alt: a(b"}") })),
                    Tri::No => {}
                }
            }
            Some(push(i, 1, None, Sit::VarIdent { end_alt: None }))
        }
        _ => None,
    }
}

fn varbrace(ctx: Ctx, h: &[u8], i: usize, l: bool) -> WhatNow {
    let need = i > 0 || l;
    let keep = push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: None });
    let remove = push(i, 2, a(b"$"), Sit::VarBrace { end_alt: a(b""), depth: 0, star: None });
    let n = identlen(&h[i + 2..]);
    let j = i + 2 + n;
    match ctx {
        Ctx::Phantom => {
            if n == 0 {
                if i + 2 >= h.len() && need {
                    return flush(i);
                }
                return keep;
            }
            if j >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j] == b'}' {
                return match braces_needed_after(h, j + 1) {
                    Tri::Maybe => {
                        if need {
                            flush(i)
                        } else {
                            keep
                        }
                    }
                    Tri::Yes => keep,
                    Tri::No => remove,
                };
            }
            if h[j] == b'[' {
                if j + 3 > h.len() {
                    if need {
                        return flush(i);
                    }
                    return keep;
                }
                if &h[j..j + 3] == b"[*]" {
                    return push(i, 2, None, Sit::VarBrace { end_alt: None, depth: 0, star: Some(n + 1) });
                }
            }
            keep
        }
        Ctx::Dq { fresh: true } => {
            if n == 0 {
                if i + 2 >= h.len() && need {
                    return flush(i);
                }
                return keep;
            }
            if j >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j] != b'}' {
                return keep;
            }
            if j + 1 >= h.len() {
                if need {
                    return flush(i);
                }
                return keep;
            }
            if h[j + 1] != b'"' {
                return keep;
            }
            match braces_needed_after(h, j + 1) {
                Tri::Maybe => {
                    if need {
                        flush(i)
                    } else {
                        keep
                    }
                }
                Tri::Yes => keep,
                Tri::No => remove,
            }
        }
        _ => keep,
    }
}

// ---------------------------------------------------------------- test

fn test(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    if h.len() < 4 && l {
        return flush(0);
    }
    if h.starts_with(b"-n ") || h.starts_with(b"-z ") {
        if h.len() > 3 {
            if let Some(wn) = common_token(Ctx::Arg, trig, h, 3, l) {
                if wn.is_flush() {
                    if l {
                        return flush(0);
                    }
                } else if wn.is_push() {
                    let insert: &'static [u8] = if h[1] == b'n' { b" != \"\"" } else { b" = \"\"" };
                    return replace(0, 3, a(b""), Sit::TestN { trig, insert, started: false });
                }
            }
        }
    }
    if h.first() == Some(&b'x') && h.len() > 1 {
        if let Some(wn) = common_token(Ctx::Arg, trig, h, 1, l) {
            if wn.is_flush() {
                if l {
                    return flush(0);
                }
            } else if wn.is_push() {
                if let Some(end) = crate::machine::simulate_token(h, wn, trig, l) {
                    let r = &h[end..];
                    let op_len = if r.starts_with(b" = x") {
                        Some(1)
                    } else if r.starts_with(b" == x") || r.starts_with(b" != x") {
                        Some(2)
                    } else {
                        if r.len() < 5 && l {
                            return flush(0);
                        }
                        None
                    };
                    if let Some(op_len) = op_len {
                        return replace(0, 1, a(b""), Sit::TestX { trig, op_len, started: false });
                    }
                }
            }
        }
    }
    replace(0, 0, None, Sit::Arg { trig })
}

// ---------------------------------------------------------------- for

fn for_(trig: Trig, h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if c == b'\n' || c == b';' {
            return pop(i, 0, None);
        }
        if is_ws(c) {
            continue;
        }
        if is_identhead(c) {
            let n = identlen(&h[i..]);
            if i + n == h.len() && (i > 0 || l) {
                return flush(i);
            }
            if &h[i..i + n] == b"in" {
                match for_special(&h[i..]) {
                    Tri::Maybe => {
                        if i > 0 || l {
                            return flush(i);
                        }
                    }
                    Tri::Yes => {
                        let pre = for_special_pre(&h[i..]);
                        return push(i, 0, None, Sit::ForArr { phase: 0, pre });
                    }
                    Tri::No => {}
                }
                return push(i, 0, None, Sit::Arg { trig });
            }
            return push(i, n, None, extent0(COLOR_LVAR));
        }
        let wn = keyword_or_command(trig, h, i, l);
        return match wn.tr {
            Tr::Push(s) => WhatNow { tr: Tr::Replace(s), pre: wn.pre, len: wn.len, alt: wn.alt },
            other => WhatNow { tr: other, pre: wn.pre, len: wn.len, alt: wn.alt },
        };
    }
    flush(h.len())
}

fn for_special_pre(h: &[u8]) -> usize {
    let mut j = 2;
    while j < h.len() && (h[j] == b' ' || h[j] == b'\t') {
        j += 1;
    }
    j
}

/// `in` + whitespace + `$ident` + spaces + (`;` | newline).
fn for_special(h: &[u8]) -> Tri {
    let j0 = for_special_pre(h);
    if j0 >= h.len() {
        return Tri::Maybe;
    }
    if j0 == 2 {
        return Tri::No;
    }
    let mut j = j0;
    if h[j] != b'$' {
        return Tri::No;
    }
    j += 1;
    if j >= h.len() {
        return Tri::Maybe;
    }
    let n = identlen(&h[j..]);
    if n == 0 {
        return Tri::No;
    }
    j += n;
    while j < h.len() && h[j] == b' ' {
        j += 1;
    }
    match h.get(j) {
        None => Tri::Maybe,
        Some(b';') | Some(b'\n') => Tri::Yes,
        _ => Tri::No,
    }
}

// ---------------------------------------------------------------- case

fn case_subj(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            let r = &h[i + 1..];
            if r.len() < 3 && (i > 0 || l) {
                if b"in".starts_with(&r[..r.len().min(2)]) {
                    return flush(i);
                }
            }
            if r.starts_with(b"in") && r.get(2).map_or(true, |&d| !is_word(d)) {
                return replace(i + 3, 0, None, Sit::CaseBody);
            }
            continue;
        }
        if let Some(wn) = common_token(Ctx::NoQuote, Trig::None, h, i, l) {
            return wn;
        }
    }
    flush(h.len())
}

fn case_body(h: &[u8], l: bool) -> WhatNow {
    for i in 0..h.len() {
        let c = h[i];
        if is_ws(c) {
            continue;
        }
        if c == b'#' {
            return push(i, 0, None, Sit::Comment);
        }
        let len = predlen(is_word, &h[i..]);
        if i + len == h.len() && (i > 0 || l) {
            return flush(i);
        }
        if &h[i..i + len] == b"esac" {
            return replace(i, 4, None, extent0(COLOR_KWD));
        }
        return push(i, 0, None, Sit::CasePattern);
    }
    flush(h.len())
}
