// The stack machine driving the situations, and the output sink.

use crate::sit::*;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mode {
    Syntax,
    Suggest,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

const CODE_DEL: u32 = 1 << 30;
const CODE_ADD: u32 = 1 << 31;

pub const BUFSIZE: usize = 128;

pub struct Sink {
    mode: Mode,
    pub buf: Vec<u8>,
    cur: u32,
}

fn write_escape(buf: &mut Vec<u8>, code: u32) {
    if code == CODE_DEL {
        buf.extend_from_slice(b"\x1b[0;41m");
        return;
    }
    if code == CODE_ADD {
        buf.extend_from_slice(b"\x1b[0;42m");
        return;
    }
    if code == COLOR_NORMAL {
        buf.extend_from_slice(b"\x1b[m");
        return;
    }
    let mut s = String::from("\x1b[0");
    if code & BOLD != 0 {
        s.push_str(";1");
    }
    if code & ITAL != 0 {
        s.push_str(";3");
    }
    let rgb = code & 0xffffff;
    if rgb != 0 {
        s.push_str(&format!(";38;2;{};{};{}", rgb >> 16, (rgb >> 8) & 0xff, rgb & 0xff));
    }
    s.push('m');
    buf.extend_from_slice(s.as_bytes());
}

impl Sink {
    pub fn new(mode: Mode) -> Sink {
        Sink { mode, buf: Vec::new(), cur: COLOR_NORMAL }
    }

    fn colored(&mut self, code: u32, bytes: &[u8]) {
        if bytes.is_empty() {
            return;
        }
        if code != self.cur {
            write_escape(&mut self.buf, code);
            self.cur = code;
        }
        self.buf.extend_from_slice(bytes);
    }

    fn is_transform(&self) -> bool {
        matches!(self.mode, Mode::Transform | Mode::Check | Mode::Replace)
    }

    pub fn plain(&mut self, color: Color, bytes: &[u8]) {
        match self.mode {
            Mode::Transform | Mode::Check | Mode::Replace => self.buf.extend_from_slice(bytes),
            Mode::Syntax | Mode::SyntaxSuggest => self.colored(color, bytes),
            Mode::Suggest => self.colored(COLOR_NORMAL, bytes),
        }
    }

    pub fn replaced(&mut self, color: Color, orig: &[u8], alt: Option<&[u8]>) {
        let alt = match alt {
            None => return self.plain(color, orig),
            Some(x) => x,
        };
        if self.is_transform() {
            self.buf.extend_from_slice(alt);
            return;
        }
        if self.mode == Mode::Syntax {
            return self.plain(color, orig);
        }
        let p = orig.iter().zip(alt.iter()).take_while(|(x, y)| x == y).count();
        self.plain(color, &orig[..p]);
        self.colored(CODE_DEL, &orig[p..]);
        self.colored(CODE_ADD, &alt[p..]);
    }

    pub fn finish(&mut self) {
        if self.cur != COLOR_NORMAL {
            write_escape(&mut self.buf, COLOR_NORMAL);
            self.cur = COLOR_NORMAL;
        }
    }
}

/// Absolute-position error.
pub enum RunErr {
    Eof,
    Pitfall { pos: usize, len: usize },
}

enum PassEnd {
    Done,
    Consumed(usize),
}

struct Machine {
    stack: Vec<Sit>,
}

impl Machine {
    /// One pass over the buffer. `base` is the absolute position of buf[0].
    fn pass(&mut self, buf: &[u8], base: usize, eof: bool, sink: &mut Sink) -> Result<PassEnd, RunErr> {
        let mut pos = 0usize;
        loop {
            let top = match self.stack.last_mut() {
                None => return Ok(PassEnd::Done),
                Some(t) => t,
            };
            let h = &buf[pos..];
            let l = !eof && !(pos == 0 && buf.len() >= BUFSIZE);
            let color_pre = top.color();
            let wn = match top.whatnow(h, l) {
                Ok(w) => w,
                Err(SynErr::Eof) => return Err(RunErr::Eof),
                Err(SynErr::Pitfall { pos: p, len }) => {
                    return Err(RunErr::Pitfall { pos: base + pos + p, len })
                }
            };
            sink.plain(color_pre, &h[..wn.pre]);
            pos += wn.pre;
            let orig = &buf[pos..pos + wn.len];
            match wn.tr {
                Tr::Flush | Tr::FlushPopOnEof => {
                    let is_pop = matches!(wn.tr, Tr::FlushPopOnEof);
                    if wn.len > 0 || wn.alt.is_some() {
                        sink.replaced(color_pre, orig, wn.alt.as_deref());
                        pos += wn.len;
                    }
                    if !eof {
                        return Ok(PassEnd::Consumed(pos));
                    }
                    if pos >= buf.len() {
                        if is_pop {
                            self.stack.pop();
                        } else {
                            return Err(RunErr::Eof);
                        }
                    }
                }
                Tr::Push(s) => {
                    let c = s.color();
                    self.stack.push(s);
                    sink.replaced(c, orig, wn.alt.as_deref());
                    pos += wn.len;
                }
                Tr::Replace(s) => {
                    let c = s.color();
                    *self.stack.last_mut().unwrap() = s;
                    sink.replaced(c, orig, wn.alt.as_deref());
                    pos += wn.len;
                }
                Tr::Pop => {
                    sink.replaced(color_pre, orig, wn.alt.as_deref());
                    pos += wn.len;
                    self.stack.pop();
                }
            }
        }
    }
}

/// Run the machine over the whole input, emulating a fixed-size read buffer.
pub fn run(inp: &[u8], sink: &mut Sink) -> Result<(), RunErr> {
    let mut m = Machine { stack: vec![root()] };
    let mut buf: Vec<u8> = Vec::with_capacity(BUFSIZE);
    let mut src = 0usize; // bytes of input moved into the buffer
    let mut base = 0usize; // absolute position of buf[0]
    let mut eof = false;
    let mut stall = 0usize;
    loop {
        if buf.len() < BUFSIZE && !eof {
            let n = (BUFSIZE - buf.len()).min(inp.len() - src);
            if n == 0 {
                eof = true;
            }
            buf.extend_from_slice(&inp[src..src + n]);
            src += n;
        }
        match m.pass(&buf, base, eof, sink)? {
            PassEnd::Done => return Ok(()),
            PassEnd::Consumed(c) => {
                if c == 0 && (buf.len() >= BUFSIZE || eof) {
                    stall += 1;
                    if stall > 3 {
                        // Should not happen; avoid hanging.
                        return Err(RunErr::Eof);
                    }
                } else {
                    stall = 0;
                }
                buf.drain(..c);
                base += c;
            }
        }
    }
}

