/// Err = need more input. Ok(Some) = $PWD replacement. Ok(None) = regular.
fn pwd_check(ctx: Ctx, h: &[u8], i: usize, open: usize, close: u8, l: bool) -> Result<Option<WhatNow>, WhatNow> {
    let need = i > 0 || l;
    let n = identlen(&h[i + open..]);
    let j = i + open + n;
    if j >= h.len() {
        return if need { Err(flush(i)) } else { Ok(None) };
    }
    if h[j] != close {
        return Ok(None);
    }
    let br = braces_needed_after(h, j + 1);
    if br == Tri::Maybe {
        return if need { Err(flush(i)) } else { Ok(None) };
    }
    if &h[i + open..j] != b"pwd" {
        return Ok(None);
    }
    let alt: &[u8] = if br == Tri::Yes {
        if close == b'`' && ctx == Ctx::NoQuote {
            return Ok(None);
        }
        b"${PWD}"
    } else {
        b"$PWD"
    };
    Ok(Some(push(i, j + 1 - i, a(alt), extent0(COLOR_VAR))))
}

fn backtick(ctx: Ctx, trig: Trig, h: &[u8], i: usize, l: bool) -> WhatNow {
