    match ctx {
        Ctx::NoQuote => push(i, 1, None, Sit::Normal { trig: Trig::Backtick, end_alt: None }),
        _ => push(i, 1, a(b"$("), Sit::Normal { trig: Trig::Backtick, end_alt: a(b")") }),
    }
}

